const CATALOGO=[
{id:"defuncion",fase:"urgente",t:"Obtener el certificado de defunción",d:"La funeraria inscribe la defunción en el Registro Civil. Pide varias copias literales: las exigen bancos, notaría, aseguradoras y organismos. Son gratuitas.",quien:"Funeraria o familia",org:"Registro Civil",docs:[],norma:"Ley 20/2011 del Registro Civil, arts. 62-66",e:TV,cuando:()=>true},
{id:"custodia",fase:"urgente",t:"Proteger los bienes sin disponer de ellos",d:"Guarda llaves, documentos y vehículos. No retires dinero de las cuentas del fallecido ni pagues con él deudas propias: puede considerarse que aceptas la herencia y ya no podrías renunciar.",quien:"Familia",org:"",docs:[],accion:{tipo:"doc",id:"banco",texto:"Carta al banco"},norma:"art. 999 CC",e:TV,cuando:()=>true},
{id:"pensionista",fase:"urgente",t:"Comunicar el fallecimiento del pensionista",d:"El INSS suele saberlo por el Registro Civil, pero conviene comunicarlo en 30 días. Se cobra íntegro el mes del fallecimiento y la parte de la paga extra; lo cobrado de más hay que devolverlo.",quien:"Familia",org:"Instituto Nacional de la Seguridad Social",plazo:(c)=>trAdm(trDias(c.fecha,30)),docs:["Certificado de defunción"],accion:{tipo:"sede",url:"https://sede.seg-social.gob.es/wps/portal/sede/sede/Ciudadanos/cita+previa+para+pensiones+y+otras+prestaciones/",texto:"Pedir cita en el INSS"},norma:"LGSS",e:TP,cuando:(c)=>c.situ.pensionista},
{id:"decesos",fase:"urgente",t:"Avisar a la aseguradora de decesos",d:"Suele cubrir el sepelio y, según la póliza, gestiones posteriores. Comprueba qué incluye antes de contratar nada aparte.",quien:"Familia",org:"Aseguradora",docs:["Póliza","Certificado de defunción"],norma:"Contrato de seguro",e:TV,cuando:(c)=>c.situ.decesos},
{id:"baja_reta",fase:"urgente",t:"Baja del autónomo en la Seguridad Social",d:"Hay que comunicar la baja en el régimen de autónomos. Se hace por Import@ss o en una oficina de la Tesorería.",quien:"Familia o gestoría",org:"Tesorería General de la Seguridad Social",plazo:(c)=>trAdm(trDias(c.fecha,6)),docs:["Certificado de defunción"],accion:{tipo:"sede",url:SEDES.bajaReta,texto:"Baja en Import@ss"},norma:"RD 84/1996, art. 32.3 (redacción del RD 643/2026); la Tesorería puede tramitarla de oficio",e:TV,cuando:(c)=>c.situ.autonomo},
{id:"baja_censal",fase:"urgente",t:"Baja en el censo de Hacienda",d:"Si el fallecido tenía actividad económica, los herederos presentan su baja censal con el modelo 036 (el 037 ya no existe).",quien:"Herederos o gestoría",org:"Agencia Tributaria",plazo:(c)=>trAdm(trMeses(c.fecha,6)),docs:["Certificado de defunción"],accion:{tipo:"sede",url:SEDES.censal,texto:"Ver en la AEAT"},norma:"RD 1065/2007, art. 11; Orden HAC/1526/2024",e:TV,cuando:(c)=>c.situ.autonomo},
{id:"empleador",fase:"urgente",t:"Avisar a la empresa y pedir la liquidación",d:"Salarios, pagas extra y vacaciones pendientes se deben a la herencia. Pide el finiquito y el certificado de retenciones.",quien:"Familia",org:"Empresa del fallecido",docs:["Certificado de defunción","Libro de familia"],norma:"Estatuto de los Trabajadores, art. 49.1.e",e:TV,cuando:(c)=>c.situ.trabajador},
{id:"desaparecido",fase:"urgente",t:"Persona desaparecida: declaración de fallecimiento",d:"Sin certificado de defunción no se puede abrir la herencia. Mientras tanto se puede pedir un defensor o la declaración de ausencia para administrar los bienes; pasados los plazos legales, el cónyuge o los parientes hasta el cuarto grado piden al juzgado la declaración de fallecimiento.",quien:"Cónyuge o familiares",org:"Juzgado de Primera Instancia del último domicilio",docs:["Denuncia de la desaparición","Pruebas de la última noticia"],norma:"arts. 181-197 CC; arts. 67-77 Ley 15/2015 de la Jurisdicción Voluntaria",e:TP,cuando:(c)=>c.situ.desaparecido},
{id:"defuncion_extranjero",fase:"urgente",t:"Inscribir la defunción ocurrida fuera de España",d:"Si el fallecido era español y murió en el extranjero, la defunción se inscribe en el Registro Civil consular o se pide su inscripción en España con el certificado extranjero apostillado o legalizado y traducido. Sin esa inscripción, notarías y organismos no admiten el fallecimiento.",quien:"Familia",org:"Consulado de España / Registro Civil",docs:["Certificado de defunción extranjero apostillado o legalizado","Traducción jurada, si hace falta","DNI o pasaporte del fallecido"],norma:"Ley 20/2011 del Registro Civil (inscripción de hechos ocurridos en el extranjero)",e:TP,cuando:(c)=>c.situ.murioFuera},
{id:"poderes",fase:"urgente",t:"Los poderes y autorizaciones del fallecido se extinguen",d:"Con la muerte se acaban los poderes notariales y las autorizaciones en cuentas que había dado. Quien los tuviera no debe usarlos: lo que haga sabiendo del fallecimiento no vincula a la herencia y puede generarle responsabilidad.",quien:"Apoderados y autorizados",org:"Notaría y bancos",docs:["Certificado de defunción"],norma:"arts. 1732 y 1738 CC",e:TP,cuando:()=>true},
{id:"funeral",fase:"urgente",t:"Pagar el sepelio y guardar las facturas",d:"Muchos bancos pagan la factura de la funeraria con cargo a la cuenta del fallecido si se la presentan directamente; pagar el entierro no supone aceptar la herencia. Guarda las facturas: los gastos de entierro y funeral se restan en el Impuesto sobre Sucesiones y justifican el auxilio por defunción.",quien:"Familia",org:"Funeraria y banco",docs:["Factura de la funeraria","Certificado de defunción"],accion:{tipo:"doc",id:"banco",texto:"Carta al banco"},norma:"art. 14.b Ley 29/1987; arts. 999 y 1894 CC",e:TP,cuando:()=>true},
{id:"personas_a_cargo",fase:"urgente",t:"Personas que dependían de él: nuevo tutor o curador",d:"Si el fallecido era tutor de un menor o curador de una persona con discapacidad, hay que pedir al juzgado que nombre a otra persona cuanto antes. Si dejó designado en testamento o escritura quién debía sustituirle, el juez lo tendrá en cuenta.",quien:"Familia",org:"Juzgado de Primera Instancia",docs:["Certificado de defunción","Resolución que le nombró tutor o curador","Testamento o escritura con la designación"],norma:"arts. 199-201 y 271-276 CC; Ley 15/2015 de la Jurisdicción Voluntaria",e:TP,cuando:(c)=>c.situ.cuidabaDependiente},
{id:"armas",fase:"urgente",t:"Depositar las armas en la Guardia Civil",d:"Los herederos o el albacea deben entregar las armas en la Intervención de Armas en cuanto lo sepan y, como tarde, en seis meses. Quedan depositadas un año para que un heredero con licencia se las quede, se vendan a quien pueda tenerlas o se conserven inutilizadas como recuerdo; después pueden destruirse.",quien:"Herederos o albacea",org:"Intervención de Armas de la Guardia Civil",plazo:(c)=>trAdm(trMeses(c.fecha,6)),docs:["Armas y guías de pertenencia","Certificado de defunción","DNI"],accion:{tipo:"sede",url:SEDES.armas,texto:"Ver en el Ministerio del Interior"},norma:"Reglamento de Armas (RD 137/1993), art. 93",e:TV,cuando:(c)=>c.situ.armas},
{id:"trabajadores",fase:"urgente",t:"Trabajadores del fallecido y empleada de hogar",d:"La muerte del empleador persona física extingue los contratos, salvo que un heredero continúe la actividad y se subrogue. Cada trabajador tiene derecho a un mes de salario además del finiquito, y hay que darle de baja en la Seguridad Social.",quien:"Herederos",org:"Tesorería General de la Seguridad Social",plazo:(c)=>trAdm(trDias(c.fecha,3),"la baja se comunica en los tres días naturales siguientes al cese"),docs:["Certificado de defunción","Contratos y nóminas"],accion:{tipo:"sede",url:SEDES.importass,texto:"Abrir Import@ss"},norma:"arts. 44 y 49.1.g Estatuto de los Trabajadores; RD 1620/2011 (empleados de hogar); RD 84/1996, art. 32",e:TP,cuando:(c)=>c.situ.empleador},
{id:"ultimas",fase:"conocer",t:"Pedir el certificado de últimas voluntades",d:"Dice si hay testamento, de qué fecha y ante qué notario. Se pide con el modelo 790 (tasa del Ministerio de Justicia), en la sede electrónica, por correo o en persona.",quien:"Cualquier interesado",org:"Ministerio de Justicia",plazo:(c)=>({desde:trHabiles(c.fecha,15)}),docs:["Certificado de defunción","Modelo 790 pagado"],accion:{tipo:"doc",id:"certificados",texto:"Ver la guía"},sede:SEDES.ultimas,norma:"Reglamento Notarial, anexo II",e:TV,cuando:()=>true},
{id:"seguros_cert",fase:"conocer",t:"Pedir el certificado de seguros de fallecimiento",d:"Lista los seguros de vida y accidentes del fallecido y las compañías. No dice quién es el beneficiario: hay que preguntarlo a cada aseguradora.",quien:"Cualquier interesado",org:"Ministerio de Justicia",plazo:(c)=>({desde:trHabiles(c.fecha,15)}),docs:["Certificado de defunción","Modelo 790 pagado"],accion:{tipo:"doc",id:"certificados",texto:"Ver la guía"},sede:SEDES.segurosCert,norma:"Ley 20/2005 del Registro de contratos de seguros",e:TV,cuando:()=>true},
{id:"testamento",fase:"conocer",t:"Pedir la copia autorizada del testamento",d:"Con el certificado de últimas voluntades, se pide al notario que lo autorizó (o a quien custodie su protocolo).",quien:"Herederos",org:"Notaría",docs:["Certificado de últimas voluntades","Certificado de defunción","DNI"],norma:"Reglamento Notarial, art. 226",e:TP,cuando:(c)=>!!c.testamento&&c.testamento!=="no"&&c.testamento!=="nose"},
{id:"olografo",fase:"conocer",t:"Adverar y protocolizar el testamento ológrafo",d:"El testamento escrito a mano solo vale si se presenta ante notario, que comprueba que es del fallecido, en los cinco años siguientes al fallecimiento. Quien lo tenga debe presentarlo en los diez días siguientes a saber del fallecimiento.",quien:"Quien lo tenga en su poder",org:"Notaría",plazo:(c)=>({limite:trMeses(c.fecha,60)}),docs:["Testamento original","Certificado de defunción","Testigos que conozcan la letra"],norma:"arts. 689-690 CC; arts. 61-63 Ley del Notariado",e:TV,cuando:(c)=>c.situ.olografo},
{id:"declaracion",fase:"conocer",t:"Acta notarial de declaración de herederos",d:"Sin testamento, el notario declara quiénes son los herederos según la ley. Hacen falta dos testigos que conozcan a la familia.",quien:"Herederos",org:"Notaría",docs:["Certificado de defunción","Certificado de últimas voluntades","Libro de familia","DNI de los herederos","Dos testigos"],accion:{tipo:"tab",tab:"reparto",texto:"Ver quién hereda"},sede:SEDES.notariado,norma:"arts. 55-56 Ley del Notariado",e:TV,cuando:(c)=>c.testamento==="no"||c.testamento==="nose"},
{id:"albacea",fase:"conocer",t:"Aceptación del albacea o contador-partidor",d:"Si el testamento nombra albacea o contador-partidor, debe aceptar el cargo. Tiene un año para cumplir su encargo, salvo que el testamento diga otra cosa.",quien:"Albacea",org:"Notaría",docs:["Copia del testamento"],norma:"arts. 892-911 y 1057 CC",e:TV,cuando:(c)=>c.situ.albacea},
{id:"seguros_vida",fase:"conocer",t:"Reclamar los seguros de vida",d:"Cada beneficiario reclama a la aseguradora. Lo que cobre tributa en el Impuesto sobre Sucesiones, con una reducción propia; si el beneficiario era quien pagaba las primas, tributa en su IRPF. Revisa también los seguros ligados a hipotecas y préstamos, que pueden cancelar la deuda.",quien:"Beneficiarios",org:"Aseguradoras",plazo:(c)=>({limite:trMeses(c.fecha,60),info:true}),docs:["Certificado de seguros","Certificado de defunción","DNI","Certificado médico de la causa (si lo piden)"],norma:"art. 23 Ley de Contrato de Seguro (prescripción de 5 años)",e:TV,cuando:()=>true},
{id:"planes",fase:"conocer",t:"Cobrar los planes de pensiones",d:"Los beneficiarios lo piden a la gestora. No tributa en Sucesiones, sino en el IRPF del beneficiario como rendimiento del trabajo. La reducción del 40 % de lo aportado antes de 2007 solo se aplica si se cobra en capital en el año del fallecimiento o en los dos siguientes.",quien:"Beneficiarios",org:"Gestora del plan",docs:["Certificado de defunción","Designación de beneficiarios"],norma:"LIRPF, art. 17.2.a",e:TV,cuando:(c)=>c.situ.planPensiones},
{id:"viudedad",fase:"conocer",t:"Pedir la pensión de viudedad u orfandad",d:"Se pide al INSS con la ayuda por defunción en una sola solicitud. Si se pide en tres meses, se cobra desde el día siguiente al fallecimiento; después, solo tres meses de atrasos. Hay orfandad hasta los 25 años y pensión en favor de otros familiares que convivían y dependían del fallecido.",quien:"Viudo, pareja o huérfanos",org:"Instituto Nacional de la Seguridad Social",plazo:(c)=>trAdm(trMeses(c.fecha,3),"",{recomendado:true}),docs:["Certificado de defunción","Libro de familia o certificado de matrimonio","DNI"],plazo2:1,accion:{tipo:"sede",url:SEDES.viudedad,texto:"Solicitar en la Seguridad Social"},norma:"arts. 219-226 y 230 LGSS",e:TV,cuando:(c)=>c.hayConyuge||c.hayMenores||c.hayHijosJovenes},
{id:"auxilio",fase:"conocer",t:"Pedir el auxilio por defunción",d:"Ayuda pública de importe fijo para quien pagó el sepelio. Se pide junto con la viudedad u orfandad, o sola.",quien:"Quien pagó el sepelio",org:"Instituto Nacional de la Seguridad Social",plazo:(c)=>({limite:trMeses(c.fecha,60),info:true}),docs:["Facturas del sepelio","Certificado de defunción"],accion:{tipo:"sede",url:SEDES.viudedad,texto:"Solicitar en la Seguridad Social"},norma:"arts. 218 y 230 LGSS",e:TV,cuando:(c)=>c.situ.pensionista||c.situ.trabajador||c.situ.autonomo},
{id:"clases_pasivas",fase:"conocer",t:"Pensiones de Clases Pasivas o de la mutualidad",d:"Si era funcionario, las pensiones de viudedad y orfandad y las ayudas de la mutualidad se piden por su propia vía.",quien:"Viudo o huérfanos",org:"Clases Pasivas (Seguridad Social) / mutualidad",docs:["Certificado de defunción","Libro de familia"],accion:{tipo:"sede",url:SEDES.clasesPasivas,texto:"Abrir Clases Pasivas"},norma:"RDLeg 670/1987",e:TP,cuando:(c)=>c.situ.funcionario},
{id:"testamento_cerrado",fase:"conocer",t:"Abrir y protocolizar el testamento cerrado",d:"Quien tenga un testamento cerrado debe presentarlo al notario en los diez días siguientes a saber del fallecimiento. El notario comprueba que la cubierta está intacta, lo abre y lo protocoliza; sin ese trámite no produce efectos.",quien:"Quien lo custodie",org:"Notaría",plazo:(c)=>({limite:trDias(c.fecha,10),recomendado:true}),docs:["Testamento cerrado","Certificado de defunción","Certificado de últimas voluntades"],norma:"arts. 712-714 CC; arts. 57-60 Ley del Notariado",e:TP,cuando:(c)=>c.situ.testamentoCerrado},
{id:"testamento_testigos",fase:"conocer",t:"Elevar a escritura el testamento hecho ante testigos",d:"El testamento otorgado sin notario en peligro de muerte o en epidemia queda ineficaz si no se acude al notario en los tres meses siguientes al fallecimiento para elevarlo a escritura pública. Declaran ante él los testigos.",quien:"Interesados",org:"Notaría",plazo:(c)=>({limite:trMeses(c.fecha,3)}),docs:["Nota escrita del testamento, si la hay","Testigos","Certificado de defunción"],norma:"arts. 700-704 CC; arts. 64-65 Ley del Notariado",e:TP,cuando:(c)=>c.situ.testamentoTestigos},
{id:"ley_aplicable",fase:"conocer",t:"Determinar qué ley rige la herencia",d:"Si el fallecido era extranjero o vivía fuera de España, la herencia se rige por la ley de su última residencia habitual, salvo que en testamento eligiera la de su nacionalidad. Si se aplica una ley extranjera, notario y registrador pedirán que se acredite su contenido.",quien:"Abogado",org:"",docs:["Testamentos españoles y extranjeros","Pasaporte y certificados de residencia"],norma:"Reglamento (UE) 650/2012, arts. 21-22; art. 36 Reglamento Hipotecario; art. 33 Ley 29/2015 de cooperación jurídica internacional",e:TP,cuando:(c)=>c.ccaa==="EST"||c.situ.nacionalidadExtranjera},
{id:"testamento_extranjero",fase:"conocer",t:"Buscar testamentos otorgados en otros países",d:"El certificado español solo muestra testamentos hechos en España. Si vivió o tenía bienes fuera, hay que consultar el registro de testamentos de cada país; un testamento extranjero necesita apostilla o legalización y traducción jurada para usarse aquí.",quien:"Abogado",org:"Registros de testamentos extranjeros / notarías",docs:["Certificado de defunción apostillado"],norma:"Convenio de Basilea de 16-5-1972 sobre registro de testamentos; Reglamento (UE) 650/2012",e:TP,cuando:(c)=>c.ccaa==="EST"||c.situ.nacionalidadExtranjera||c.situ.extranjero},
{id:"vecindad_civil",fase:"conocer",t:"Comprobar la vecindad civil del fallecido",d:"Cataluña, Aragón, Navarra, País Vasco, Galicia y Baleares tienen reglas propias sobre legítimas, viudo y forma de testar. Se aplican según la vecindad civil del fallecido, no según dónde vivía: se adquiere por nacimiento, por residir diez años sin declarar lo contrario o por opción.",quien:"Abogado",org:"Registro Civil",docs:["Certificado de nacimiento","Declaraciones de vecindad, si las hay","Padrón histórico"],norma:"arts. 9.8 y 14-16 CC",e:TP,cuando:(c)=>FORAL.includes(c.ccaa)||c.situ.vinculoForal},
{id:"pareja_registro",fase:"conocer",t:"Certificado de la pareja de hecho",d:"La pareja inscrita se equipara al cónyuge en el Impuesto sobre Sucesiones en la mayoría de comunidades y puede tener derecho a viudedad si se inscribió al menos dos años antes. En derecho común no hereda sin testamento.",quien:"Pareja",org:"Registro de parejas de hecho autonómico o municipal",docs:["DNI"],norma:"art. 221 LGSS; normativa autonómica de parejas de hecho y del Impuesto sobre Sucesiones",e:TP,cuando:(c)=>c.civil==="pareja"},
{id:"herencia_estado",fase:"conocer",t:"Sin herederos: hereda la Administración",d:"Si no hay testamento, ni cónyuge, ni parientes hasta el cuarto grado, hereda el Estado o, en algunas comunidades con derecho propio, la comunidad autónoma. Se tramita una declaración administrativa de heredero; quien tenga bienes o créditos del fallecido debe comunicarlo.",quien:"Administración",org:"Delegación de Economía y Hacienda / comunidad autónoma",docs:["Certificado de defunción","Certificado de últimas voluntades"],norma:"arts. 956-958 CC; arts. 20.6 y 20 bis Ley 33/2003 del Patrimonio de las Administraciones Públicas",e:TP,cuando:(c)=>c.testamento==="no"&&c.nHerederos===0},
{id:"ius_transmissionis",fase:"conocer",t:"Heredero que muere sin aceptar: derecho de transmisión",d:"Si un heredero muere después del causante sin haber aceptado ni renunciado, su derecho pasa a sus propios herederos, que pueden aceptar o renunciar esa primera herencia. Según el Tribunal Supremo hay una sola adquisición desde el primer causante, también a efectos del impuesto.",quien:"Herederos del heredero",org:"Notaría",docs:["Certificados de defunción de ambos","Títulos sucesorios de ambos"],norma:"art. 1006 CC; jurisprudencia del Tribunal Supremo (2018)",e:TP,cuando:(c)=>c.situ.herederoFallecido},
{id:"historia_clinica",fase:"conocer",t:"Pedir la historia clínica",d:"Los familiares pueden obtener la historia clínica del fallecido, salvo que él lo prohibiera expresamente. Suele hacer falta para cobrar seguros de vida o accidentes y para valorar una reclamación por negligencia.",quien:"Familiares",org:"Hospital o centro de salud",docs:["Certificado de defunción","Acreditación del parentesco","DNI"],norma:"art. 18.4 Ley 41/2002 de autonomía del paciente",e:TV,cuando:(c)=>c.situ.accidente},
{id:"indemnizacion_accidente",fase:"conocer",t:"Reclamar la indemnización por la muerte",d:"Si murió en un accidente de tráfico, laboral o por una posible negligencia, los familiares perjudicados (no la herencia) pueden reclamar al responsable o a su aseguradora. Los plazos son cortos: un año en tráfico y en reclamaciones a la sanidad pública. Si fue accidente de trabajo hay además prestaciones especiales de la Seguridad Social.",quien:"Familiares perjudicados",org:"Aseguradora del responsable / Administración / INSS",plazo:(c)=>({limite:trMeses(c.fecha,12),info:true,nota:"plazo general de un año; revisar el aplicable"}),docs:["Atestado o informe del accidente","Historia clínica","Certificado de defunción","Libro de familia"],norma:"RDLeg 8/2004 (responsabilidad civil en la circulación), art. 7, y baremo de la Ley 35/2015; art. 1968.2 CC; art. 67 Ley 39/2015; art. 227 LGSS",e:TP,cuando:(c)=>c.situ.accidente},
{id:"seguro_convenio",fase:"conocer",t:"Seguro de vida del convenio colectivo",d:"Muchos convenios obligan a la empresa a tener un seguro de vida o accidentes para su plantilla. Pregunta a la empresa o a los representantes de los trabajadores; el beneficiario lo reclama a la aseguradora.",quien:"Beneficiarios",org:"Empresa y aseguradora",docs:["Certificado de defunción","Convenio colectivo aplicable"],norma:"Convenio colectivo aplicable; art. 23 Ley de Contrato de Seguro",e:TP,cuando:(c)=>c.situ.trabajador},
{id:"paro",fase:"conocer",t:"Comunicar al SEPE y cobrar lo pendiente del paro",d:"La prestación o el subsidio se extingue con el fallecimiento. Los herederos pueden pedir al SEPE lo devengado y no cobrado hasta ese día.",quien:"Herederos",org:"Servicio Público de Empleo Estatal",docs:["Certificado de defunción","Acreditación de ser heredero"],norma:"LGSS, título III (protección por desempleo)",e:TP,cuando:(c)=>c.situ.paro},
{id:"dependencia",fase:"conocer",t:"Dependencia, residencia y ayudas sociales",d:"Comunica el fallecimiento a los servicios sociales: la prestación de dependencia se extingue y lo cobrado de más hay que devolverlo. Si vivía en una residencia, liquida la última factura, recupera la fianza y revisa si quedaban cantidades pendientes de cobro.",quien:"Familia",org:"Servicios sociales de la comunidad autónoma / residencia",docs:["Certificado de defunción"],norma:"Ley 39/2006 de dependencia y normativa autonómica",e:TP,cuando:(c)=>c.situ.dependencia},
{id:"mutualidad",fase:"conocer",t:"Mutualidad profesional y colegio",d:"La mutualidad (abogacía, medicina, arquitectura, etc.) puede pagar capital de fallecimiento, viudedad u orfandad según el plan contratado. Comunica también la baja al colegio y organiza la custodia o entrega de los expedientes o historias de sus clientes o pacientes.",quien:"Familia o beneficiarios",org:"Mutualidad y colegio profesional",docs:["Certificado de defunción","Libro de familia"],norma:"Estatutos y reglamento de la mutualidad; normativa colegial",e:TP,cuando:(c)=>c.situ.colegiado},
{id:"viudedad_exconyuge",fase:"conocer",t:"Pensión de viudedad del excónyuge",d:"El divorciado o separado puede tener derecho a viudedad si cobraba una pensión compensatoria que se extingue con la muerte, en proporción al tiempo convivido. Hay excepciones para víctimas de violencia de género.",quien:"Excónyuge",org:"Instituto Nacional de la Seguridad Social",plazo:(c)=>trAdm(trMeses(c.fecha,3),"",{recomendado:true}),docs:["Sentencia de divorcio o separación","Certificado de defunción","DNI"],accion:{tipo:"sede",url:SEDES.viudedad,texto:"Solicitar en la Seguridad Social"},norma:"art. 220 LGSS",e:TP,cuando:(c)=>c.situ.exconyuge},
{id:"bancos_cert",fase:"inventario",t:"Certificados de saldos y posiciones",d:"Saldo de cada cuenta, depósito y valor a la fecha del fallecimiento, con los titulares y autorizados.",quien:"Herederos",org:"Bancos",docs:["Certificado de defunción","Certificado de últimas voluntades","Testamento o declaración de herederos"],accion:{tipo:"doc",id:"banco",texto:"Carta al banco"},norma:"art. 9 Ley 29/1987 (valor real)",e:TV,cuando:(c)=>c.hayCuentas||c.hayValores},
{id:"nota_simple",fase:"inventario",t:"Nota simple de cada inmueble",d:"Confirma quién es el titular, en qué proporción y si hay cargas o hipotecas.",quien:"Cualquiera",org:"Registro de la Propiedad",docs:["Dirección o datos registrales"],accion:{tipo:"sede",url:SEDES.notaSimple,texto:"Pedir nota simple (9,02 €)"},norma:"Ley Hipotecaria, arts. 221-222",e:TV,cuando:(c)=>c.inmuebles>0},
{id:"valor_ref",fase:"inventario",t:"Valor de referencia de cada inmueble",d:"Hacienda toma como mínimo el valor de referencia del Catastro a la fecha del fallecimiento. Se consulta gratis con certificado o Cl@ve.",quien:"Herederos",org:"Catastro",docs:["Referencia catastral"],accion:{tipo:"sede",url:SEDES.valorRef,texto:"Consultar el valor de referencia"},norma:"art. 9.3 Ley 29/1987",e:TV,cuando:(c)=>c.inmuebles>0},
{id:"ibi",fase:"inventario",t:"Último recibo del IBI de cada inmueble",d:"Trae el valor catastral total y el del suelo, que hacen falta para la plusvalía. Hereda+ puede leerlo de una foto.",quien:"Herederos",org:"Ayuntamiento",docs:["Recibo del IBI"],accion:{tipo:"tab",tab:"patrimonio",texto:"Completar inmuebles"},norma:"art. 107.2.a TRLRHL",e:TV,cuando:(c)=>c.inmuebles>0},
{id:"vehiculos_valor",fase:"inventario",t:"Valorar los vehículos",d:"Se valoran con las tablas de precios medios que publica cada año el Ministerio de Hacienda, según marca, modelo y antigüedad.",quien:"Herederos",org:"Hacienda",docs:["Permiso de circulación","Ficha técnica"],norma:"Orden anual de precios medios de venta",e:TV,cuando:(c)=>c.hayVehiculos},
{id:"empresa_valor",fase:"inventario",t:"Valorar la empresa o las participaciones",d:"Balances, cuentas y certificado de participaciones. Determina si procede la reducción por empresa familiar.",quien:"Asesor",org:"Empresa / Registro Mercantil",docs:["Estatutos","Últimas cuentas anuales","Libro registro de socios"],norma:"art. 20.2.c Ley 29/1987 y normativa autonómica",e:TV,cuando:(c)=>c.hayEmpresa},
{id:"deudas_cert",fase:"inventario",t:"Certificados de deudas pendientes",d:"Hipoteca, préstamos y tarjetas a la fecha del fallecimiento. Las deudas del fallecido restan en la herencia.",quien:"Herederos",org:"Bancos y acreedores",docs:[],norma:"art. 13 Ley 29/1987",e:TV,cuando:(c)=>c.hayDeudas},
{id:"deudas_publicas",fase:"inventario",t:"Comprobar deudas con Hacienda y el ayuntamiento",d:"Antes de aceptar, conviene saber si hay deudas tributarias (AEAT, comunidad autónoma, IBI) y el informe de riesgos del Banco de España (CIRBE), que muestra préstamos y avales. Las multas y sanciones no se heredan.",quien:"Herederos",org:"AEAT, hacienda autonómica, ayuntamiento, Banco de España",docs:[],accion:{tipo:"sede",url:SEDES.cirbe,texto:"Pedir el informe CIRBE"},norma:"LGT arts. 39.1 y 190.1",e:TV,cuando:()=>true},
{id:"donaciones",fase:"inventario",t:"Revisar donaciones previas",d:"Las donaciones del fallecido al mismo heredero en los cuatro años anteriores se suman para calcular el tipo del impuesto, y algunas deben traerse a la partición (colación).",quien:"Herederos",org:"",docs:["Escrituras de donación"],norma:"art. 30 Ley 29/1987; art. 1035 CC",e:TV,cuando:()=>true},
{id:"gananciales",fase:"inventario",t:"Separar lo ganancial de lo privativo",d:"Antes de repartir hay que liquidar la sociedad de gananciales: la mitad de lo común es del viudo y no se hereda.",quien:"Viudo y herederos",org:"",docs:["Certificado de matrimonio","Escrituras de compra"],accion:{tipo:"tab",tab:"patrimonio",texto:"Revisar bienes"},norma:"arts. 1344, 1392 y 1396-1410 CC",e:TV,cuando:(c)=>c.civil==="gananciales"},
{id:"extranjero",fase:"inventario",t:"Bienes fuera de España",d:"Se aplica el Reglamento europeo de sucesiones: una sola ley a toda la herencia y el certificado sucesorio europeo para actuar en otros países de la UE.",quien:"Abogado",org:"Notaría",docs:[],norma:"Reglamento (UE) 650/2012",e:TV,cuando:(c)=>c.situ.extranjero},
{id:"digital",fase:"inventario",t:"Herencia digital",d:"Cuentas de correo, redes, nube y monederos. Herederos y albacea pueden pedir acceso o borrado a los prestadores, salvo que el fallecido lo prohibiera.",quien:"Herederos",org:"Prestadores de servicios",docs:["Certificado de defunción","Acreditación de heredero"],norma:"Ley Orgánica 3/2018, art. 96",e:TV,cuando:()=>true},
{id:"localizar_inmuebles",fase:"inventario",t:"Localizar los inmuebles a nombre del fallecido",d:"El Catastro expide a los herederos un certificado con todos los inmuebles que figuran a nombre del fallecido. En el Registro de la Propiedad se puede consultar además el índice de titularidades para encontrar fincas desconocidas.",quien:"Herederos",org:"Catastro / Registro de la Propiedad",docs:["Certificado de defunción","Acreditación del parentesco o título sucesorio"],accion:{tipo:"sede",url:SEDES.catastroHeredero,texto:"Certificado de inmuebles del fallecido"},norma:"art. 53 RDLeg 1/2004 (Catastro); art. 222 Ley Hipotecaria",e:TV,cuando:()=>true},
{id:"creditos",fase:"inventario",t:"Cobrar lo que se le debía",d:"También son herencia las devoluciones de Hacienda, las fianzas de alquiler, los préstamos que hizo a familiares o a terceros, salarios o facturas pendientes e indemnizaciones. Lo que un heredero le debía se descuenta de su parte.",quien:"Herederos",org:"",docs:["Contratos o justificantes de los créditos"],norma:"arts. 659 y 661 CC",e:TP,cuando:()=>true},
{id:"ajuar",fase:"inventario",t:"Decidir cómo computar el ajuar doméstico",d:"La ley presume que el ajuar vale el 3 % del caudal, pero según el Tribunal Supremo solo comprende los muebles y enseres de uso personal y doméstico: no se calcula sobre cuentas, acciones ni inmuebles distintos de la vivienda. Se puede declarar un valor menor si se prueba.",quien:"Herederos",org:"Hacienda autonómica",docs:[],accion:{tipo:"tab",tab:"impuestos",texto:"Ver el cálculo"},norma:"art. 15 Ley 29/1987; STS (Sala 3.ª) de 10-3-2020",e:TP,cuando:()=>true},
{id:"gastos_deducibles",fase:"inventario",t:"Reunir las facturas deducibles",d:"En el Impuesto sobre Sucesiones se restan los gastos justificados de última enfermedad, entierro y funeral, y los de un litigio sobre la herencia en interés común de los herederos. Hay que acreditarlos con factura.",quien:"Herederos",org:"Hacienda autonómica",docs:["Facturas médicas, de la funeraria y del litigio"],norma:"art. 14 Ley 29/1987",e:TV,cuando:()=>true},
{id:"bienes_adicionables",fase:"inventario",t:"Revisar ventas y retiradas del último año",d:"Hacienda presume que siguen en la herencia los bienes que el fallecido tenía en el año anterior a su muerte, salvo que se pruebe que se transmitieron y están en poder de otra persona. Hay reglas parecidas para bienes con usufructo y valores depositados.",quien:"Herederos",org:"Hacienda autonómica",docs:["Extractos bancarios del último año","Escrituras de venta"],norma:"art. 11 Ley 29/1987",e:TV,cuando:()=>true},
{id:"cuentas_cotitulares",fase:"inventario",t:"Cuentas con varios titulares",d:"Ser cotitular de una cuenta indistinta no da la propiedad del dinero: se presume por partes iguales, salvo prueba de quién lo aportó. Se incluye en la herencia la parte del fallecido y el cotitular no debe vaciarla.",quien:"Herederos y cotitulares",org:"Bancos",docs:["Certificado del banco con titulares y saldos","Origen de los fondos"],norma:"art. 393 CC; jurisprudencia del Tribunal Supremo sobre cuentas indistintas",e:TP,cuando:(c)=>c.hayCuentas},
{id:"caja_seguridad",fase:"inventario",t:"Abrir la caja de seguridad",d:"El banco no entrega el contenido sin acreditar quiénes son los herederos. Lo prudente es abrirla ante notario, que levanta acta de lo que hay, para incluirlo en el inventario y evitar discusiones.",quien:"Herederos y notario",org:"Banco / notaría",docs:["Contrato de la caja","Título sucesorio","Certificado de defunción"],norma:"art. 8.1.a Ley 29/1987; actas de presencia (Reglamento Notarial, art. 199)",e:TP,cuando:(c)=>c.situ.cajaSeguridad},
{id:"cripto",fase:"inventario",t:"Criptomonedas y monederos digitales",d:"Localiza exchanges y monederos (móvil, ordenador, frases semilla en papel). Los exchanges piden el título sucesorio; sin las claves de un monedero propio los fondos son irrecuperables. Se valoran a la cotización del día del fallecimiento.",quien:"Herederos",org:"Exchanges / custodios",docs:["Certificado de defunción","Título sucesorio","Extractos del exchange"],norma:"art. 9 Ley 29/1987 (valor real); art. 96 LO 3/2018",e:TP,cuando:(c)=>c.situ.cripto},
{id:"arte",fase:"inventario",t:"Joyas, obras de arte y colecciones",d:"Se valoran aparte del ajuar, a precio de mercado y con tasación de un experto si su valor lo justifica. Los bienes del Patrimonio Histórico tienen una reducción del 95 % para cónyuge y descendientes y pueden entregarse en pago de impuestos.",quien:"Herederos y tasador",org:"Hacienda autonómica / Ministerio de Cultura",docs:["Tasación","Facturas o certificados de autenticidad"],norma:"arts. 9 y 20.2.c Ley 29/1987; art. 73 Ley 16/1985 del Patrimonio Histórico Español",e:TP,cuando:(c)=>c.situ.arte},
{id:"avales",fase:"inventario",t:"Avales y fianzas que había firmado",d:"Si el fallecido avaló préstamos o alquileres de otros, esa garantía pasa a los herederos que acepten. Pide al banco y a la CIRBE el detalle antes de decidir si se acepta y cómo.",quien:"Herederos",org:"Bancos / Banco de España",docs:["Informe CIRBE","Contratos de aval"],accion:{tipo:"sede",url:SEDES.cirbe,texto:"Pedir el informe CIRBE"},norma:"arts. 1003, 1257 y 1911 CC",e:TP,cuando:(c)=>c.situ.avalista},
{id:"reservas",fase:"inventario",t:"Bienes sujetos a reserva o troncalidad",d:"Algunos bienes que el fallecido recibió gratis de su familia tienen un destino fijado por la ley: la reserva troncal los devuelve a la línea de parientes de la que proceden, la del viudo que volvió a casarse reserva a los hijos del primer matrimonio lo recibido del cónyuge anterior y en varios derechos forales rige la troncalidad. Hay que identificarlos antes de repartir.",quien:"Abogado",org:"",docs:["Títulos de adquisición de esos bienes"],norma:"arts. 811 y 968-980 CC; derechos forales (troncalidad)",e:TP,cuando:(c)=>c.situ.bienesFamiliares},
{id:"inventario_plazo",fase:"urgente",t:"Si hay deudas: aceptar a beneficio de inventario",d:"Para no responder de las deudas con su propio patrimonio, el heredero puede aceptar a beneficio de inventario ante notario: solo responde hasta donde alcancen los bienes heredados (arts. 1010, 1011 y 1023 CC). Plazo: si tiene en su poder bienes de la herencia, 30 días desde que sabe que es heredero (art. 1014); si no los tiene ni ha actuado como heredero, 30 días desde que vence el plazo que se le fije para aceptar o repudiar, o desde que acepta o actúa como heredero (art. 1015); fuera de esos casos, mientras no prescriba la acción para reclamar la herencia y no haya demanda contra él (art. 1016). Cualquier acto de aceptación tácita (art. 999) cierra esta vía.",quien:"Cada heredero",org:"Notaría",plazo:()=>({nota:"30 días desde que sabe que es heredero si tiene bienes de la herencia en su poder (art. 1014 CC); si no, arts. 1015-1016 CC"}),docs:["Certificado de defunción","Relación de deudas conocidas"],norma:"arts. 999, 1010-1016 y 1023 CC",e:TV,cuando:(c)=>c.hayDeudas||c.pasivoExcede||c.situ.avalista},
{id:"aceptar",fase:"decidir",t:"Decidir si se acepta o se renuncia",d:"Cada heredero decide. Aceptar sin más obliga a responder de las deudas con los bienes propios; si hay dudas, se acepta a beneficio de inventario ante notario (con plazo de 30 días desde que sabe que es heredero si ya tiene bienes de la herencia en su poder: arts. 1014-1016 CC).",quien:"Cada heredero",org:"",docs:[],accion:{tipo:"ia",texto:"Preguntar a Hereda+"},norma:"arts. 988-1034 CC",e:TV,cuando:()=>true},
{id:"renuncia",fase:"decidir",t:"Firmar la renuncia ante notario",d:"La renuncia es irrevocable y solo vale ante notario. Hay que firmarla antes de hacer nada que suponga aceptar.",quien:"Quien renuncia",org:"Notaría",docs:["DNI","Certificado de defunción","Últimas voluntades"],accion:{tipo:"doc",id:"renuncia",texto:"Minuta de renuncia"},norma:"arts. 1008 y 999 CC",e:TV,cuando:(c)=>c.hayRenuncia},
{id:"interpelacion",fase:"decidir",t:"Si alguien no se decide: interpelación notarial",d:"Pasados nueve días del fallecimiento, cualquier interesado puede pedir al notario que requiera al heredero indeciso: si no responde en 30 días naturales, se entiende que acepta pura y simplemente, también las deudas.",quien:"Cualquier interesado",org:"Notaría",docs:[],norma:"arts. 1004 y 1005 CC",e:TV,cuando:(c)=>c.nHerederos>1},
{id:"menores",fase:"decidir",t:"Herederos menores: defensor y autorización judicial",d:"Si padres e hijos menores heredan a la vez hay conflicto de intereses (defensor judicial). Para renunciar en nombre de un menor hace falta autorización judicial.",quien:"Representantes legales",org:"Juzgado o letrado de la Administración de Justicia",docs:[],norma:"arts. 163, 166 y 1060 CC",e:TV,cuando:(c)=>c.hayMenores},
{id:"legitimas",fase:"decidir",t:"Comprobar las legítimas",d:"El testamento debe respetar la parte que la ley reserva a hijos, padres o viudo. Si no, se puede reclamar.",quien:"Abogado",org:"",docs:["Copia del testamento"],accion:{tipo:"tab",tab:"reparto",texto:"Ver el reparto"},norma:"arts. 806-822 CC",e:TV,cuando:(c)=>c.testamento==="porcentajes"},
{id:"conmutacion",fase:"decidir",t:"Valorar la conmutación del usufructo del viudo",d:"Los herederos pueden pagar al viudo su usufructo con una renta, bienes o dinero, si hay acuerdo o lo decide el juez.",quien:"Viudo y herederos",org:"",docs:[],norma:"arts. 839-840 CC",e:TV,cuando:(c)=>c.hayConyuge&&c.nHerederos>1},
{id:"acuerdo",fase:"decidir",t:"Acuerdo entre herederos para gestionar",d:"Quién coordina, cómo se adelantan y reparten los gastos y cómo se informa a todos.",quien:"Herederos",org:"",docs:[],accion:{tipo:"doc",id:"acuerdo",texto:"Acuerdo entre herederos"},norma:"arts. 393 y 1064 CC",e:TV,cuando:(c)=>c.nHerederos>1},
{id:"particion",fase:"decidir",t:"Preparar la partición",d:"Inventario, avalúo, liquidación y adjudicación de los bienes a cada heredero, con compensaciones si hace falta.",quien:"Abogado y herederos",org:"",docs:[],accion:{tipo:"doc",id:"cuaderno",texto:"Cuaderno particional"},norma:"arts. 1051-1087 CC",e:TV,cuando:(c)=>c.nHerederos>1},
{id:"sin_acuerdo",fase:"decidir",t:"Si no hay acuerdo: contador-partidor o juez",d:"Los herederos que sumen la mitad del caudal pueden pedir al notario un contador-partidor dativo; si no, cabe la división judicial.",quien:"Abogado",org:"Notaría o juzgado",docs:[],norma:"art. 1057 CC; arts. 782 y ss. LEC",e:TV,cuando:(c)=>c.nHerederos>1},
{id:"deliberar",fase:"decidir",t:"Pedir tiempo para decidir: derecho a deliberar",d:"Si hay dudas sobre las deudas, el heredero puede pedir al notario que se forme inventario antes de decidir. Terminado el inventario tiene 30 días para aceptar o renunciar; si no dice nada, se entiende que acepta pura y simplemente.",quien:"Heredero",org:"Notaría",docs:["Certificado de defunción","Título sucesorio"],norma:"arts. 1010, 1014 y 1019 CC",e:TP,cuando:(c)=>c.hayDeudas},
{id:"inventario_notarial",fase:"decidir",t:"Formar el inventario del beneficio de inventario",d:"El notario cita a acreedores y legatarios; el inventario se empieza en 30 días desde la citación y se termina en otros 60. Mientras dura, la herencia se administra aparte y se paga a los acreedores sin tocar el patrimonio del heredero.",quien:"Heredero y notario",org:"Notaría",docs:["Relación de bienes y deudas","Datos de acreedores y legatarios"],norma:"arts. 1011-1034 CC",e:TP,cuando:(c)=>c.hayDeudas},
{id:"concurso_herencia",fase:"decidir",t:"Más deudas que bienes: concurso de la herencia",d:"Mientras no se haya aceptado pura y simplemente, se puede pedir el concurso de la herencia para liquidarla de forma ordenada. Pueden solicitarlo los herederos, el administrador de la herencia o los acreedores.",quien:"Herederos, administrador o acreedores",org:"Juzgado de lo Mercantil",docs:["Inventario de bienes y deudas"],norma:"arts. 567-571 TR Ley Concursal (RDLeg 1/2020)",e:TP,cuando:(c)=>c.hayDeudas},
{id:"renuncia_traslativa",fase:"decidir",t:"Renunciar sin coste fiscal: renuncia pura",d:"Renunciar a favor de una persona concreta, o a cambio de algo, equivale a aceptar y donar: se paga el impuesto dos veces. La renuncia pura y gratuita beneficia a quien marque la ley o el testamento. Los acreedores del que renuncia pueden pedir al juez cobrar con su parte.",quien:"Quien renuncia",org:"Notaría",docs:[],norma:"arts. 1000 y 1001 CC; art. 28 Ley 29/1987",e:TP,cuando:(c)=>c.hayRenuncia},
{id:"apoyos",fase:"decidir",t:"Heredero con curador o medidas de apoyo",d:"El curador con facultades de representación necesita autorización judicial para renunciar a la herencia o aceptarla sin beneficio de inventario, y la partición en que intervenga debe aprobarla después el juez. Si el apoyo es solo asistencial, firma el heredero asistido por el curador.",quien:"Curador",org:"Juzgado",docs:["Resolución judicial de apoyos"],norma:"arts. 287 y 289 CC",e:TP,cuando:(c)=>c.situ.apoyos},
{id:"discapacidad",fase:"decidir",t:"Heredero con discapacidad: reducción y protección",d:"Aporta el certificado de discapacidad para aplicar la reducción específica del Impuesto sobre Sucesiones, mayor a partir del 65 %. El testamento puede dejarle además un derecho de habitación sobre la vivienda que no computa en la legítima de los demás.",quien:"Heredero o su representante",org:"Hacienda autonómica",docs:["Certificado de grado de discapacidad"],norma:"art. 20.2.a Ley 29/1987 y normativa autonómica; art. 822 CC",e:TP,cuando:(c)=>c.hayDiscapacidad||c.situ.discapacidad},
{id:"nasciturus",fase:"decidir",t:"Viuda o pareja embarazada: esperar al parto",d:"El concebido hereda si nace con vida. Si la viuda queda encinta, la partición se suspende hasta el parto y se pueden pedir medidas para asegurar los derechos del que va a nacer.",quien:"Viuda y herederos",org:"Juzgado (si hacen falta medidas)",docs:["Certificado médico del embarazo"],norma:"arts. 29-30 y 959-967 CC",e:TP,cuando:(c)=>c.situ.embarazo},
{id:"heredero_ilocalizable",fase:"decidir",t:"Heredero en paradero desconocido",d:"Sin él no se puede firmar la partición por acuerdo. Se puede pedir al juzgado un defensor del desaparecido o la declaración de ausencia, o acudir a un contador-partidor dativo que haga la partición y reserve su parte.",quien:"Abogado",org:"Juzgado / notaría",docs:["Intentos de localización"],norma:"arts. 181-184 y 1057 CC; arts. 67-73 Ley 15/2015 de la Jurisdicción Voluntaria",e:TP,cuando:(c)=>c.situ.herederoIlocalizable},
{id:"colacion",fase:"decidir",t:"Traer a la partición las donaciones (colación)",d:"Lo que un heredero forzoso recibió en vida del fallecido se descuenta de su parte, salvo que el donante lo dispensara. Se computa por su valor al tiempo de la partición, no por el de la donación.",quien:"Herederos forzosos",org:"",docs:["Escrituras de donación","Justificantes de transferencias"],norma:"arts. 1035-1050 CC",e:TP,cuando:(c)=>c.nHerederos>1},
{id:"cautela_socini",fase:"decidir",t:"Usufructo universal del viudo: aceptarlo o pedir la legítima",d:"Si el testamento deja al viudo el usufructo de todo, los hijos pueden aceptarlo o exigir su legítima libre de cargas. Si el testamento incluye la cautela socini, quien exija la legítima pierde lo que el testador le dejaba de más. Conviene decidirlo antes de la escritura.",quien:"Hijos y viudo",org:"",docs:["Copia del testamento"],norma:"arts. 813 y 820.3 CC",e:TP,cuando:(c)=>c.testamento==="usufructo"},
{id:"pago_metalico",fase:"decidir",t:"Pagar la legítima en dinero",d:"Si el testamento lo prevé, el testador o el contador-partidor autorizado puede adjudicar bienes a un hijo y pagar a los demás su legítima en dinero, aunque no lo haya en la herencia. La decisión debe comunicarse en un año desde el fallecimiento y el pago hacerse en otro año.",quien:"Herederos o contador-partidor",org:"Notaría",plazo:(c)=>({limite:trMeses(c.fecha,12)}),docs:["Copia del testamento","Valoración de los bienes"],norma:"arts. 841-847 y 1056 CC",e:TP,cuando:(c)=>c.testamento==="porcentajes"&&c.nHerederos>1},
{id:"vivienda_viudo",fase:"decidir",t:"Atribución preferente de la vivienda al viudo",d:"Al liquidar los gananciales, el viudo puede pedir que se le adjudique la vivienda habitual y el negocio que llevaba, compensando si su mitad no alcanza, o que se le atribuya un derecho de uso o habitación.",quien:"Viudo",org:"",docs:["Escritura de la vivienda"],norma:"arts. 1406 y 1407 CC",e:TP,cuando:(c)=>c.civil==="gananciales"&&c.hayConyuge&&c.inmuebles>0},
{id:"pension_compensatoria",fase:"decidir",t:"Pensión compensatoria a cargo del fallecido",d:"La pensión compensatoria al excónyuge no se extingue con la muerte: la pagan los herederos, que pueden pedir al juez reducirla o suprimirla si la herencia no alcanza o afecta a sus legítimas. La pensión de alimentos a los hijos, en cambio, se extingue.",quien:"Herederos",org:"Juzgado de familia",docs:["Sentencia o convenio regulador"],norma:"arts. 101 y 150 CC",e:TP,cuando:(c)=>c.situ.exconyuge},
{id:"retracto_coherederos",fase:"decidir",t:"Venta de su parte por un heredero: retracto",d:"Si un heredero vende su cuota de la herencia a un extraño antes de la partición, los demás pueden quedársela pagando el mismo precio en el mes siguiente a que se les comunique la venta.",quien:"Coherederos",org:"",docs:["Escritura de venta"],norma:"art. 1067 CC",e:TP,cuando:(c)=>c.nHerederos>1},
{id:"masc",fase:"decidir",t:"Antes de demandar: intento de acuerdo",d:"Desde abril de 2025 la mayoría de demandas civiles exigen acreditar un intento previo de solución (negociación entre abogados, mediación, conciliación u oferta vinculante). Documéntalo también antes de una división judicial de la herencia.",quien:"Abogado",org:"",docs:["Justificante del intento de acuerdo"],norma:"LO 1/2025, de eficiencia del Servicio Público de Justicia, arts. 2, 5 y 7",e:TP,cuando:(c)=>c.situ.litigio},
{id:"division_judicial",fase:"decidir",t:"División judicial de la herencia",d:"Cualquier coheredero puede pedir al juzgado que haga la partición: se forma inventario, se designa contador-partidor y peritos, y si alguien se opone a las operaciones divisorias se resuelve en juicio verbal.",quien:"Abogado y procurador",org:"Juzgado de Primera Instancia",docs:["Certificado de defunción","Título sucesorio","Relación de bienes"],norma:"arts. 782-789 LEC",e:TP,cuando:(c)=>c.situ.litigio&&c.nHerederos>1},
{id:"intervencion_caudal",fase:"decidir",t:"Proteger los bienes mientras se litiga",d:"Si hay riesgo de que alguien disponga de los bienes, se puede pedir al juez la intervención del caudal: inventario, depósito de dinero y documentos, y un administrador judicial que rinde cuentas.",quien:"Abogado",org:"Juzgado de Primera Instancia",docs:[],norma:"arts. 790-805 LEC",e:TP,cuando:(c)=>c.situ.litigio},
{id:"yacente_representacion",fase:"decidir",t:"Demandas contra la herencia antes de aceptar",d:"Mientras nadie acepte, la herencia yacente puede ser demandada y litigar por medio de quien la administre; si no hay nadie, el juez puede nombrar un administrador. Los acreedores no tienen que esperar a que se acepte.",quien:"Abogado",org:"Juzgado",docs:[],norma:"arts. 6.1.4.º, 7.5 y 790-798 LEC",e:TP,cuando:(c)=>c.situ.litigio||c.hayDeudas},
{id:"impugnar_testamento",fase:"decidir",t:"Impugnar el testamento",d:"Se puede pedir la nulidad si faltan formalidades, si el testador no tenía capacidad o si hubo engaño, violencia o intimidación. Se tramita en juicio ordinario y la prueba corresponde a quien impugna: reúne pronto informes médicos y testigos.",quien:"Abogado",org:"Juzgado de Primera Instancia",docs:["Copia del testamento","Historia clínica"],norma:"arts. 663, 673 y 687 CC",e:TP,cuando:(c)=>c.situ.litigio&&hayTest(c)},
{id:"reclamar_legitima",fase:"decidir",t:"Reclamar la legítima, la preterición o reducir donaciones",d:"El heredero forzoso que recibe menos de su legítima puede pedir el complemento; si el testamento lo omite sin mencionarlo, puede impugnar por preterición. Las donaciones en vida que excedan de lo que se podía dar se reducen (donaciones inoficiosas).",quien:"Abogado",org:"Juzgado de Primera Instancia",docs:["Copia del testamento","Inventario valorado","Escrituras de donación"],norma:"arts. 636, 654-656, 814 y 815-820 CC",e:TP,cuando:(c)=>c.situ.litigio&&hayTest(c)},
{id:"desheredacion",fase:"decidir",t:"Desheredación: comprobar la causa",d:"Solo vale si el testamento expresa una causa legal. Si el desheredado la niega, son los demás herederos quienes deben probarla; si no se prueba, el desheredado recupera su legítima.",quien:"Abogado",org:"Juzgado de Primera Instancia",docs:["Copia del testamento","Pruebas de la causa"],norma:"arts. 848-857 CC",e:TP,cuando:(c)=>c.situ.desheredacion},
{id:"indignidad",fase:"decidir",t:"Indignidad para suceder",d:"No puede heredar quien cometió ciertos actos graves contra el fallecido (por ejemplo, condena por atentar contra su vida, maltrato o impedirle hacer testamento). La acción caduca a los cinco años desde que el indigno tomó posesión de los bienes.",quien:"Abogado",org:"Juzgado de Primera Instancia",docs:[],norma:"arts. 756-762 CC",e:TP,cuando:(c)=>c.situ.litigio},
{id:"peticion_herencia",fase:"decidir",t:"Reclamar la herencia a quien la posee",d:"Quien se considera heredero y ve que otros se han quedado con los bienes puede ejercitar la acción de petición de herencia para que se le reconozca y se le entreguen.",quien:"Abogado",org:"Juzgado de Primera Instancia",docs:["Título sucesorio"],norma:"arts. 192 y 1016 CC; jurisprudencia del Tribunal Supremo",e:TP,cuando:(c)=>c.situ.litigio},
{id:"filiacion",fase:"decidir",t:"Reclamación de filiación de un posible hijo",d:"Un hijo no reconocido puede reclamar la filiación después del fallecimiento y, si prospera, entra como heredero forzoso. Cabe la prueba biológica; no conviene cerrar la partición sin valorar el riesgo.",quien:"Abogado",org:"Juzgado de Primera Instancia",docs:[],norma:"arts. 131-133 CC; arts. 764-768 LEC",e:TP,cuando:(c)=>c.situ.filiacion},
{id:"cat_derecho",fase:"decidir",t:"Cataluña: legítima, inventario y pago",d:"La legítima catalana es una cuarta parte y el heredero puede pagarla en dinero o en bienes; la acción para reclamarla prescribe a los diez años. El heredero que toma inventario en seis meses solo responde de las deudas con los bienes heredados.",quien:"Abogado",org:"",plazo:(c)=>({limite:trMeses(c.fecha,6),recomendado:true,nota:"toma de inventario: seis meses desde que conoce la delación"}),docs:[],norma:"Libro IV del Código civil de Cataluña (Ley 10/2008), arts. 451-1 a 451-27 y 461-14 a 461-16",e:TP,cuando:(c)=>c.ccaa==="CAT"},
{id:"cat_viudo",fase:"decidir",t:"Cataluña: cuarta viudal y año de luto",d:"El viudo o conviviente en pareja estable sin recursos suficientes puede reclamar la cuarta viudal, hasta una cuarta parte de la herencia. Durante el primer año tiene además derecho a seguir en la vivienda y a alimentos a cargo de la herencia (any de plor).",quien:"Viudo o pareja",org:"",docs:[],norma:"arts. 231-31 y 452-1 a 452-6 del Código civil de Cataluña",e:TP,cuando:(c)=>c.ccaa==="CAT"&&c.hayConyuge},
{id:"ara_derecho",fase:"decidir",t:"Aragón: legítima colectiva y responsabilidad limitada",d:"La legítima aragonesa es la mitad del caudal y el testador puede repartirla entre los descendientes como quiera. El heredero responde de las deudas solo con los bienes heredados. La Ley 1/2025 de Aragón ha reformado reglas sucesorias: revisa la redacción vigente.",quien:"Abogado",org:"",docs:[],norma:"Código del Derecho Foral de Aragón (DLeg 1/2011), arts. 355 y 486",e:TP,cuando:(c)=>c.ccaa==="ARA"},
{id:"ara_viudedad",fase:"decidir",t:"Aragón: usufructo de viudedad",d:"El viudo tiene usufructo sobre todos los bienes del fallecido, salvo renuncia o pacto en contra. Los nudos propietarios pueden exigir inventario de los bienes usufructuados.",quien:"Viudo y herederos",org:"Notaría",docs:[],norma:"arts. 271-302 del Código del Derecho Foral de Aragón",e:TP,cuando:(c)=>c.ccaa==="ARA"&&c.hayConyuge},
{id:"nav_derecho",fase:"decidir",t:"Navarra: libertad de testar y usufructo de fidelidad",d:"La legítima navarra es solo formal: el testador puede dejar sus bienes a quien quiera si menciona a sus herederos forzosos. El viudo tiene el usufructo de fidelidad sobre todos los bienes, con obligación de hacer inventario.",quien:"Abogado",org:"",docs:[],norma:"Compilación de Derecho Civil Foral de Navarra (Fuero Nuevo), leyes 253-267",e:TP,cuando:(c)=>c.ccaa==="NAV"},
{id:"pv_derecho",fase:"decidir",t:"País Vasco: legítima de un tercio y derechos del viudo",d:"La legítima de los descendientes es un tercio y el testador puede repartirla entre ellos como quiera. El viudo tiene usufructo de la mitad de los bienes si hay descendientes y de dos tercios si no. Son frecuentes el poder testatorio y el testamento mancomunado.",quien:"Abogado",org:"",docs:[],norma:"Ley 5/2015 de Derecho Civil Vasco, arts. 47-58",e:TP,cuando:(c)=>PV.includes(c.ccaa)},
{id:"pv_troncalidad",fase:"decidir",t:"Bizkaia, Aramaio y Llodio: bienes troncales",d:"Los inmuebles de la Tierra Llana de Bizkaia, Aramaio y Llodio que proceden de la familia son troncales: deben quedar en la línea de parientes de la que proceden y los tronqueros tienen preferencia si se venden. Identifícalos antes de repartir.",quien:"Abogado",org:"",docs:["Títulos de adquisición de los inmuebles"],norma:"Ley 5/2015 de Derecho Civil Vasco, arts. 61 y ss.",e:TP,cuando:(c)=>c.ccaa==="BIZ"||c.ccaa==="ALA"},
{id:"gal_derecho",fase:"decidir",t:"Galicia: legítima de un cuarto y pactos sucesorios",d:"Solo son legitimarios los descendientes y el viudo: la legítima de los hijos es una cuarta parte y el viudo tiene un usufructo. Revisa si hubo pactos de mejora o apartación en vida, que cambian el reparto.",quien:"Abogado",org:"",docs:[],norma:"Ley 2/2006 de Derecho Civil de Galicia, arts. 209-227 y 238-258",e:TP,cuando:(c)=>c.ccaa==="GAL"},
{id:"bal_derecho",fase:"decidir",t:"Baleares: legítimas propias, definición y finiquito",d:"En Mallorca y Menorca la legítima de los hijos es un tercio o la mitad según su número y el viudo tiene usufructo; los hijos pueden haber renunciado en vida a la legítima mediante definición. En Ibiza y Formentera existe el finiquito, equivalente.",quien:"Abogado",org:"",docs:[],norma:"Compilación de Derecho Civil de las Illes Balears (DLeg 79/1990), arts. 42-53 y 77-80",e:TP,cuando:(c)=>c.ccaa==="BAL"},
{id:"ext_baylio",fase:"decidir",t:"Extremadura: comprobar si rige el Fuero del Baylío",d:"En Jerez de los Caballeros, Olivenza, Alburquerque y otros municipios de Badajoz, el matrimonio sujeto a este fuero hace comunes todos los bienes: al morir uno, todo se divide por mitad entre el viudo y los herederos, incluidos los bienes heredados o donados. Cambia el inventario.",quien:"Abogado",org:"",docs:["Certificados de matrimonio y empadronamiento"],norma:"Fuero del Baylío (costumbre reconocida; Resolución DGRN de 6-5-2015)",e:TP,cuando:(c)=>c.ccaa==="EXT"&&(c.hayConyuge||c.civil==="gananciales")},
{id:"fiducia",fase:"decidir",t:"Reparto encargado a un fiduciario o comisario",d:"En varios derechos forales el testador puede encargar a su cónyuge u otra persona que decida después cómo se reparte la herencia. Mientras no lo haga, la herencia queda pendiente de asignación, con plazos para ejercer el encargo y reglas propias en el impuesto.",quien:"Fiduciario o comisario",org:"Notaría",docs:["Testamento o pacto con el nombramiento"],norma:"Aragón: arts. 439-463 CDFA; País Vasco: arts. 30-46 Ley 5/2015; Navarra: Fuero Nuevo, leyes 281 y ss.; Galicia: Ley 2/2006, arts. 196 y ss.",e:TP,cuando:(c)=>c.situ.fiducia},
{id:"pacto_sucesorio",fase:"decidir",t:"Pactos sucesorios y donaciones a cuenta",d:"En los derechos forales se puede heredar por pacto firmado en vida (heredamiento, pacto de mejora, apartación, definición). Lo recibido cuenta en el reparto y tiene su propio tratamiento en el impuesto; en derecho común, las donaciones a cuenta de la legítima se imputan a ella.",quien:"Abogado",org:"Notaría",docs:["Escritura del pacto o de la donación"],norma:"arts. 819 y 1035 CC; derechos civiles forales",e:TP,cuando:(c)=>c.situ.pactoSucesorio},
{id:"legados",fase:"formalizar",t:"Entregar los legados",d:"El legatario no puede tomar el legado por sí mismo: se lo entregan los herederos o el albacea.",quien:"Herederos",org:"Notaría",docs:["Copia del testamento"],norma:"art. 885 CC",e:TV,cuando:(c)=>c.hayLegados},
{id:"escritura",fase:"formalizar",t:"Escritura de aceptación y partición",d:"Todos los herederos firman ante notario el reparto. Es el título para inscribir inmuebles y cobrar saldos.",quien:"Herederos",org:"Notaría",docs:["Todo el inventario","Testamento o declaración de herederos","DNI de todos"],accion:{tipo:"doc",id:"cuaderno",texto:"Cuaderno particional"},sede:SEDES.notariado,norma:"arts. 1058 CC; art. 14 Ley Hipotecaria",e:TV,cuando:(c)=>!c.herederoUnico||c.hayConyuge},
{id:"instancia",fase:"formalizar",t:"Instancia de heredero único",d:"Si hay un solo heredero y no hay otros legitimarios, puede inscribir los inmuebles con una solicitud privada, sin escritura.",quien:"Heredero",org:"Registro de la Propiedad",docs:["Testamento o declaración de herederos","Justificante del impuesto"],accion:{tipo:"doc",id:"unico",texto:"Instancia"},norma:"art. 14 Ley Hipotecaria; art. 79 Reglamento Hipotecario",e:TV,cuando:(c)=>c.herederoUnico&&c.inmuebles>0&&!c.hayConyuge},
{id:"prorroga",fase:"formalizar",t:"Pedir la prórroga del impuesto si hace falta",d:"Seis meses más para presentar, con intereses de demora. Se pide dentro de los cinco primeros meses.",quien:"Herederos",org:"Hacienda autonómica",plazo:(c)=>trAdm(trMeses(c.fecha,5)),docs:["Certificado de defunción","Relación aproximada de bienes"],accion:{tipo:"doc",id:"prorroga",texto:"Solicitud de prórroga"},sedeFn:(c)=>c.ccaa==="AND"?SEDES.ata659:null,norma:"art. 68 RD 1629/1991 (en Andalucía, modelo 659)",e:TV,cuando:()=>true},
{id:"isd",fase:"formalizar",t:"Presentar y pagar el Impuesto sobre Sucesiones",d:"Una autoliquidación por heredero y la relación de bienes. Hay que presentarla aunque salga a pagar 0 €. En Andalucía, modelos 650 y 660 ante la Agencia Tributaria de Andalucía.",quien:"Cada heredero (o su abogado)",org:"Hacienda autonómica",plazo:(c)=>trISD(c),docs:["Inventario valorado","Testamento o declaración de herederos","Certificados bancarios","Valores de referencia"],accion:{tipo:"tab",tab:"impuestos",texto:"Ver el cálculo"},sedeFn:(c)=>c.ccaa==="AND"?SEDES.ata650:null,norma:"arts. 67-68 RD 1629/1991; art. 31 Ley 29/1987",e:TV,cuando:()=>true},
{id:"plusvalia",fase:"formalizar",t:"Declarar la plusvalía y pedir la bonificación",d:"Por cada inmueble urbano, aunque no haya ganancia. Las bonificaciones por herencia a familiares no se aplican solas: hay que pedirlas en plazo. La prórroga se pide al ayuntamiento dentro de los seis meses y es independiente de la del Impuesto sobre Sucesiones.",quien:"Herederos",org:"Ayuntamiento",plazo:(c)=>trAdm(trMeses(c.fecha,6),"prorrogable hasta "+aHabil(trMeses(c.fecha,12))+"; la prórroga del Impuesto sobre Sucesiones no la amplía"),docs:["Escritura o declaración de herederos","Recibo del IBI","Título de adquisición del fallecido"],accion:{tipo:"tab",tab:"impuestos",texto:"Ver el cálculo"},norma:"art. 110 TRLRHL",e:TV,cuando:(c)=>c.inmuebles>0},
{id:"plusvalia_real",fase:"formalizar",t:"Plusvalía: acreditar que no hubo ganancia o tributar por la real",d:"Si el inmueble vale menos que cuando lo adquirió el fallecido, no hay plusvalía municipal: se acredita con su título de adquisición y el valor declarado en el Impuesto sobre Sucesiones. Si hubo ganancia pero menor que la del cálculo objetivo, se puede pedir tributar por la real.",quien:"Herederos",org:"Ayuntamiento",plazo:(c)=>trAdm(trMeses(c.fecha,6),"con la declaración de la plusvalía"),docs:["Título de adquisición del fallecido","Autoliquidación del Impuesto sobre Sucesiones"],accion:{tipo:"tab",tab:"impuestos",texto:"Ver el cálculo"},norma:"arts. 104.5 y 107.5 TRLRHL",e:TP,cuando:(c)=>c.inmuebles>0},
{id:"isd_no_residente",fase:"formalizar",t:"Impuesto sobre Sucesiones ante la AEAT (no residentes)",d:"Si el fallecido no residía en España, el impuesto se presenta ante la Agencia Tributaria con el modelo 650. Se puede aplicar la normativa de la comunidad donde esté la mayor parte de los bienes. Cada heredero no residente debe nombrar un representante con residencia en España.",quien:"Cada heredero",org:"Agencia Tributaria",plazo:(c)=>trISD(c),docs:["Certificado de defunción apostillado","Título sucesorio","NIE","Valoración de los bienes en España"],accion:{tipo:"sede",url:SEDES.aeat650,texto:"Modelo 650 en la AEAT"},norma:"disposición adicional 2.ª Ley 29/1987; art. 18.4 RD 1629/1991",e:TV,cuando:(c)=>c.ccaa==="EST"},
{id:"nie",fase:"formalizar",t:"NIE para los herederos extranjeros",d:"El heredero extranjero necesita NIE para firmar la escritura, pagar el impuesto e inscribir los bienes. Se pide en España ante la Policía o desde fuera en el consulado. Si no reside en España, debe nombrar además un representante para el Impuesto sobre Sucesiones.",quien:"Herederos extranjeros",org:"Policía Nacional / consulado",docs:["Pasaporte","Justificante del interés (herencia)","Tasa modelo 790 código 012"],accion:{tipo:"sede",url:SEDES.nie,texto:"Asignación de NIE"},norma:"art. 206 RD 557/2011 (Reglamento de Extranjería); RD 1065/2007, arts. 18 y 20; art. 18.4 RD 1629/1991",e:TP,cuando:(c)=>c.situ.herederoExtranjero},
{id:"apostilla",fase:"formalizar",t:"Documentos extranjeros: apostilla y traducción",d:"Certificados, testamentos y poderes extranjeros necesitan apostilla o legalización, según el país, y traducción jurada. Entre países de la UE, los certificados de defunción, nacimiento y matrimonio están exentos de apostilla y pueden acompañarse de formulario multilingüe.",quien:"Abogado",org:"Autoridad del país de origen / traductor jurado",docs:[],accion:{tipo:"sede",url:SEDES.apostilla,texto:"Apostillar documentos españoles"},norma:"Convenio de La Haya de 5-10-1961; Reglamento (UE) 2016/1191; art. 36 Reglamento Hipotecario",e:TP,cuando:(c)=>internacional(c)},
{id:"cse",fase:"formalizar",t:"Certificado sucesorio europeo",d:"Acredita la condición de heredero, legatario o albacea en otros países de la UE (salvo Dinamarca e Irlanda) sin más trámites. En España lo expide el notario o el juzgado que tramite la sucesión; sus copias valen seis meses prorrogables.",quien:"Herederos o albacea",org:"Notaría",docs:["Título sucesorio","Relación de bienes en el extranjero"],accion:{tipo:"sede",url:SEDES.ejusticia,texto:"Portal Europeo de e-Justicia"},norma:"Reglamento (UE) 650/2012, arts. 62-73; disposición final 26.ª LEC",e:TP,cuando:(c)=>c.situ.extranjero||c.ccaa==="EST"},
{id:"sucesion_extranjero",fase:"formalizar",t:"Trámites sucesorios en el país de los bienes",d:"Cada país exige su propio procedimiento para liberar cuentas o inscribir inmuebles (probate en el Reino Unido, Erbschein en Alemania, etc.). Fuera de la UE no sirve el certificado sucesorio europeo y suele hacer falta un abogado local.",quien:"Abogado y corresponsal local",org:"Autoridades del país",docs:["Título sucesorio apostillado y traducido"],norma:"Reglamento (UE) 650/2012 y ley del país de situación",e:TP,cuando:(c)=>c.situ.extranjero},
{id:"doble_imposicion",fase:"formalizar",t:"Descontar el impuesto pagado en el extranjero",d:"Si por los bienes situados fuera se paga un impuesto similar en otro país, en el impuesto español se deduce la menor de dos cantidades: lo pagado fuera o lo que correspondería en España por esos bienes. Guarda el justificante del pago extranjero.",quien:"Herederos",org:"Hacienda autonómica o AEAT",docs:["Liquidación y pago del impuesto extranjero"],norma:"art. 23 Ley 29/1987",e:TV,cuando:(c)=>c.situ.extranjero},
{id:"pago_cuentas",fase:"formalizar",t:"Pagar el impuesto con el dinero de las cuentas",d:"Aunque las cuentas estén bloqueadas, el banco puede emitir un cheque a nombre de la Administración con cargo a ellas para pagar el Impuesto sobre Sucesiones; no se considera entrega de la herencia. Pídelo por escrito con la autoliquidación.",quien:"Herederos",org:"Banco",docs:["Autoliquidación del impuesto","Título sucesorio","Certificado de defunción"],accion:{tipo:"doc",id:"banco",texto:"Carta al banco"},norma:"art. 8.1.a Ley 29/1987; art. 19 RD 1629/1991",e:TV,cuando:(c)=>c.hayCuentas||c.hayValores},
{id:"aplazamiento",fase:"formalizar",t:"Aplazar o fraccionar el Impuesto sobre Sucesiones",d:"Si en la herencia no hay dinero suficiente, se puede pedir aplazamiento de hasta un año o fraccionamiento en hasta cinco anualidades, con intereses y, en su caso, garantía. Si se hereda la vivienda habitual o una empresa, cabe un aplazamiento especial de cinco años. Se pide dentro del plazo de presentación.",quien:"Herederos",org:"Hacienda autonómica",plazo:(c)=>trISD(c,"dentro del plazo de presentación"),docs:["Solicitud motivada","Autoliquidación","Garantía, si se exige"],norma:"art. 38 Ley 29/1987; arts. 79-86 RD 1629/1991; art. 65 LGT",e:TP,cuando:()=>true},
{id:"excesos_adjudicacion",fase:"formalizar",t:"Excesos de adjudicación en la partición",d:"Si un heredero se queda con más de lo que le toca y compensa en dinero a los demás, el exceso tributa en Transmisiones Patrimoniales, salvo que el bien sea indivisible o pierda mucho valor al dividirse (como una vivienda), o se trate del pago de la legítima en dinero o de la conmutación del viudo.",quien:"Heredero adjudicatario",org:"Hacienda autonómica",plazo:()=>({nota:"plazo del ITP desde la escritura, según la comunidad"}),docs:["Escritura de partición"],norma:"art. 7.2.B RDLeg 1/1993 (ITP y AJD); arts. 821, 829, 1056 y 1062 CC",e:TV,cuando:(c)=>c.nHerederos>1&&c.inmuebles>0},
{id:"explotacion_agraria",fase:"formalizar",t:"Reducciones por explotación agraria",d:"La transmisión por herencia de una explotación agraria prioritaria, o de fincas para completarla, tiene reducciones de entre el 75 % y el 100 % o exención si se cumplen los requisitos y se mantiene indivisa cinco años. Las comunidades pueden añadir reducciones propias.",quien:"Herederos",org:"Hacienda autonómica",plazo:(c)=>({limite:trMeses(c.fecha,60),info:true,nota:"mantener la explotación cinco años"}),docs:["Certificado de explotación prioritaria","Título sucesorio"],norma:"arts. 9, 10, 11 y 20 Ley 19/1995 de Modernización de las Explotaciones Agrarias",e:TV,cuando:(c)=>c.situ.pac||c.situ.ganado||c.situ.rustica},
{id:"consolidacion_usufructo",fase:"formalizar",t:"Se extingue un usufructo del fallecido: consolidación",d:"Si el fallecido era usufructuario (por ejemplo, del cónyuge que murió antes o de bienes que donó reservándose el usufructo), el usufructo se extingue y los nudos propietarios pasan a ser plenos dueños. Deben liquidar el impuesto pendiente por la consolidación y cancelar el usufructo en el Registro.",quien:"Nudos propietarios",org:"Hacienda autonómica / Registro de la Propiedad",plazo:(c)=>trAdm(trMeses(c.fecha,6)),docs:["Certificado de defunción","Título que constituyó el usufructo"],norma:"art. 26.c Ley 29/1987; art. 51 RD 1629/1991",e:TP,cuando:(c)=>c.situ.usufructuario},
{id:"inmatriculacion",fase:"formalizar",t:"Inmuebles sin inscribir o a nombre de otros",d:"Si una finca no está inscrita o figura a nombre de un antepasado, hay que regularizarla para inscribir la herencia. Si la herencia anterior no se formalizó, a menudo basta con otorgarla en la misma escritura (tracto abreviado); si no, inmatriculación o reanudación del tracto por expediente notarial.",quien:"Abogado y notaría",org:"Notaría / Registro de la Propiedad",docs:["Títulos de propiedad disponibles","Certificación catastral descriptiva y gráfica"],norma:"arts. 20, 203, 205 y 208 Ley Hipotecaria",e:TP,cuando:(c)=>c.situ.sinInscribir},
{id:"obra_nueva",fase:"formalizar",t:"Declarar obras o ampliaciones no inscritas",d:"Las construcciones o ampliaciones que no constan en el Registro deben declararse para que la herencia refleje la realidad. Si ya no cabe actuación urbanística por el tiempo transcurrido, se declaran como obra antigua con certificado técnico.",quien:"Herederos, técnico y notaría",org:"Notaría / Registro / Catastro",docs:["Certificado técnico de antigüedad","Certificación catastral"],norma:"art. 28.4 RDLeg 7/2015 (Ley de Suelo y Rehabilitación Urbana); art. 202 Ley Hipotecaria",e:TP,cuando:(c)=>c.situ.obraSinDeclarar},
{id:"registro",fase:"titularidad",t:"Inscribir los inmuebles a nombre de los herederos",d:"El Registro exige haber presentado el Impuesto sobre Sucesiones y haber comunicado la plusvalía.",quien:"Herederos o notaría",org:"Registro de la Propiedad",docs:["Escritura o instancia","Justificante del impuesto","Comunicación de plusvalía"],norma:"art. 33 Ley 29/1987; art. 254 Ley Hipotecaria",e:TV,cuando:(c)=>c.inmuebles>0},
{id:"catastro",fase:"titularidad",t:"Cambio de titular en el Catastro",d:"Normalmente lo comunican el notario o el registrador. Comprueba después que figura bien para los recibos del IBI.",quien:"Notaría o Registro",org:"Catastro",docs:[],accion:{tipo:"sede",url:SEDES.catastro,texto:"Comprobar en el Catastro"},norma:"Ley del Catastro Inmobiliario, art. 14",e:TP,cuando:(c)=>c.inmuebles>0},
{id:"bancos_titularidad",fase:"titularidad",t:"Cobrar saldos y cambiar la titularidad en los bancos",d:"Con la escritura y el justificante del impuesto, el banco transfiere los saldos o cambia los titulares y cancela lo del fallecido.",quien:"Herederos",org:"Bancos",docs:["Escritura de partición","Justificante del impuesto"],norma:"art. 8 Ley 29/1987 (responsabilidad del banco)",e:TP,cuando:(c)=>c.hayCuentas||c.hayValores},
{id:"dgt_custodia",fase:"urgente",t:"Si alguien usa el coche antes del reparto",d:"Quien vaya a conducirlo antes de repartir la herencia debe comunicarlo a Tráfico como poseedor (tasa 4.1).",quien:"Heredero que lo use",org:"Dirección General de Tráfico",plazo:(c)=>trAdm(trDias(c.fecha,90)),docs:["Permiso de circulación","Certificado de defunción"],accion:{tipo:"sede",url:SEDES.dgtCust,texto:"Ver en la DGT"},norma:"Reglamento General de Vehículos, art. 32.6",e:TV,condicional:"Solo si alguien usa el vehículo antes del reparto",cuando:(c)=>c.hayVehiculos},
{id:"dgt",fase:"titularidad",t:"Transferir los vehículos",d:"El heredero adjudicatario pide el cambio de titularidad por herencia (tasa 1.5), o la baja si no se va a usar. Tiene 90 días desde el documento de adjudicación.",quien:"Heredero adjudicatario",org:"Dirección General de Tráfico",plazo:()=>({nota:"90 días desde la escritura o documento de adjudicación"}),docs:["Permiso de circulación","Documento de herencia","Justificante del impuesto","DNI"],accion:{tipo:"sede",url:SEDES.dgtAdj,texto:"Ver en la DGT"},norma:"Reglamento General de Vehículos, art. 32",e:TV,cuando:(c)=>c.hayVehiculos},
{id:"suministros",fase:"titularidad",t:"Luz, agua, gas y teléfono",d:"Cambio de titular o baja de cada suministro. La cuenta de cargo del fallecido acabará bloqueada.",quien:"Herederos",org:"Compañías",docs:["Certificado de defunción","Documento de herencia"],norma:"",e:TV,cuando:(c)=>c.inmuebles>0},
{id:"comunidad",fase:"titularidad",t:"Comunidad de propietarios",d:"Comunicar el fallecimiento y los nuevos titulares, y la cuenta para las cuotas.",quien:"Herederos",org:"Administrador de fincas",docs:[],norma:"Ley de Propiedad Horizontal, art. 9.1.i",e:TV,cuando:(c)=>c.inmuebles>0},
{id:"seguros_bienes",fase:"titularidad",t:"Seguros de hogar, coche y salud",d:"Cambio de tomador o baja. El seguro de hogar sigue cubriendo la vivienda mientras se reparte.",quien:"Herederos",org:"Aseguradoras",docs:["Certificado de defunción"],norma:"Ley de Contrato de Seguro, arts. 34 y 37 (aviso en 15 días)",e:TV,cuando:(c)=>c.inmuebles>0||c.hayVehiculos},
{id:"alquiler_inquilino",fase:"titularidad",t:"Subrogación en el alquiler de su vivienda",d:"Si el fallecido vivía de alquiler, pueden seguir en el contrato el cónyuge o pareja y ciertos familiares que convivieran con él. El aviso va por escrito al arrendador, con el certificado de defunción y quién sigue; si no llega en tres meses, el contrato se extingue.",quien:"Conviviente",org:"Arrendador",plazo:(c)=>({limite:trMeses(c.fecha,3)}),docs:["Certificado de defunción","Empadronamiento"],norma:"Ley de Arrendamientos Urbanos, art. 16",e:TV,cuando:(c)=>c.situ.inquilino},
{id:"local_negocio",fase:"titularidad",t:"Local de negocio alquilado",d:"Si el fallecido tenía un negocio en un local alquilado, el heredero que continúe la actividad puede subrogarse avisando al arrendador en dos meses.",quien:"Heredero que continúa",org:"Arrendador",plazo:(c)=>({limite:trMeses(c.fecha,2)}),docs:["Certificado de defunción"],norma:"Ley de Arrendamientos Urbanos, art. 33",e:TV,cuando:(c)=>c.situ.localNegocio},
{id:"herencia_yacente",fase:"titularidad",t:"Rentas antes del reparto: NIF de la herencia",d:"Si hay alquileres o actividad antes de repartir, la herencia yacente necesita NIF y sus rentas se atribuyen a los herederos.",quien:"Herederos o gestoría",org:"Agencia Tributaria",docs:[],accion:{tipo:"sede",url:SEDES.aeat,texto:"Abrir la sede de la AEAT"},norma:"LIRPF, régimen de atribución de rentas",e:TP,cuando:(c)=>c.situ.arrendador||c.situ.autonomo},
{id:"alquiler_arrendador",fase:"titularidad",t:"Comunicar a los inquilinos el nuevo arrendador",d:"Los herederos se subrogan como arrendadores: nueva cuenta para las rentas, fianza y declaración de los rendimientos.",quien:"Herederos",org:"Inquilinos",docs:[],norma:"Ley de Arrendamientos Urbanos",e:TV,cuando:(c)=>c.situ.arrendador},
{id:"empresa_rm",fase:"titularidad",t:"Cambio de socio o administrador de la empresa",d:"En una SL, la sociedad anota a los herederos en el libro registro de socios; los estatutos pueden dar a los socios tres meses para comprar las participaciones. Si el fallecido era administrador, hay que nombrar otro, y si queda un socio único se inscribe la unipersonalidad en seis meses.",quien:"Empresa",org:"Sociedad / Registro Mercantil",docs:["Escritura de partición","Estatutos"],norma:"LSC arts. 13-14, 104-106, 110 y 171",e:TV,cuando:(c)=>c.hayEmpresa},
{id:"animales",fase:"titularidad",t:"Cambio de titular de los animales",d:"Los animales se adjudican atendiendo a su bienestar y se actualiza el registro de identificación (en Andalucía, el RAIA) con el nuevo responsable.",quien:"Nuevo responsable",org:"Veterinario / registro autonómico",docs:[],norma:"art. 914 bis CC; Ley 7/2023 de bienestar animal; Decreto 92/2005 de Andalucía",e:TP,cuando:(c)=>c.situ.animales},
{id:"sepultura",fase:"titularidad",t:"Titularidad de la sepultura o nicho",d:"El derecho funerario se transmite según la ordenanza del cementerio. Hay que pedir el cambio de titular.",quien:"Herederos",org:"Cementerio o ayuntamiento",docs:["Título de la sepultura","Documento de herencia"],norma:"Ordenanza municipal de cementerios",e:TP,cuando:(c)=>c.situ.sepultura},
{id:"hipoteca",fase:"titularidad",t:"Hipoteca y préstamos del fallecido",d:"Los herederos que aceptan asumen los préstamos. Comunícalo al banco y revisa si había seguro de vida o de amortización que los cancele. Si era una hipoteca inversa, los herederos pueden pagar lo debido y conservar el inmueble o dejar que el banco se cobre con él.",quien:"Herederos",org:"Banco",docs:["Certificado de deuda a la fecha","Póliza del seguro vinculado"],norma:"arts. 659, 661 y 1911 CC; disposición adicional 1.ª Ley 41/2007 (hipoteca inversa); art. 82 Ley Hipotecaria",e:TP,cuando:(c)=>c.hayDeudas&&c.inmuebles>0},
{id:"fin_alquiler_inquilino",fase:"titularidad",t:"Si nadie sigue en su alquiler: entregar la vivienda",d:"Si ningún conviviente se subroga, el contrato se extingue. Los herederos entregan las llaves, pagan la renta hasta la entrega y reclaman la fianza, que el arrendador debe devolver en un mes desde la entrega.",quien:"Herederos",org:"Arrendador",docs:["Contrato","Justificante de la fianza"],norma:"arts. 16 y 36.4 Ley de Arrendamientos Urbanos",e:TP,cuando:(c)=>c.situ.inquilino},
{id:"renta_antigua",fase:"titularidad",t:"Contratos de renta antigua (anteriores a 1985)",d:"Los alquileres anteriores al 9 de mayo de 1985 tienen reglas propias: normalmente solo cabe una subrogación más, a favor del cónyuge o de un hijo conviviente, y a veces por tiempo limitado. Revísalo tanto si el fallecido era inquilino como si era arrendador.",quien:"Herederos / conviviente",org:"Arrendador o inquilino",docs:["Contrato original"],norma:"disposición transitoria 2.ª Ley de Arrendamientos Urbanos",e:TP,cuando:(c)=>c.situ.inquilino||c.situ.arrendador},
{id:"vut",fase:"titularidad",t:"Viviendas de uso turístico: nuevo titular o cese",d:"El heredero que siga explotándola debe comunicar el cambio de titular en el registro de turismo de la comunidad (en Andalucía, el Registro de Turismo de Andalucía) y actualizar el registro de viajeros; si no la va a explotar, debe comunicar el cese. El registro único estatal de arrendamientos fue anulado en parte por el Tribunal Supremo en 2026: comprueba su situación.",quien:"Heredero que la explote",org:"Consejería de turismo / Ministerio del Interior",docs:["Título sucesorio","Nota simple actualizada","DNI"],sedeFn:(c)=>c.ccaa==="AND"?SEDES.rta:null,norma:"normativa turística autonómica (en Andalucía, Decreto 28/2016); RD 933/2021 (registro de viajeros); RD 1312/2024",e:TP,cuando:(c)=>c.situ.vut},
{id:"vpo",fase:"titularidad",t:"Vivienda protegida: comunicar la herencia",d:"Heredar una vivienda protegida no suele necesitar autorización previa, pero hay que comunicarlo y el heredero queda sujeto a sus limitaciones: precio máximo, destino a residencia habitual y derechos de tanteo y retracto de la Administración si la vende.",quien:"Herederos",org:"Consejería de vivienda de la comunidad",docs:["Cédula de calificación","Título sucesorio"],norma:"normativa autonómica de vivienda protegida (en Andalucía, Decreto 149/2006)",e:TP,cuando:(c)=>c.situ.vpo},
{id:"cooperativa",fase:"titularidad",t:"Participación en una cooperativa",d:"Los herederos pueden suceder al fallecido como socios si ya lo son o si la cooperativa los admite; si no, tienen derecho al reembolso de sus aportaciones. En una cooperativa de viviendas esto decide quién se queda la vivienda adjudicada.",quien:"Herederos",org:"Cooperativa",docs:["Certificado de aportaciones","Estatutos","Título sucesorio"],norma:"art. 50.b Ley 27/1999 de Cooperativas y leyes autonómicas (en Andalucía, Ley 14/2011)",e:TP,cuando:(c)=>c.situ.cooperativa},
{id:"pac",fase:"titularidad",t:"Ayudas agrarias (PAC): cambio de titular",d:"Comunica el fallecimiento a la consejería de agricultura y pide la cesión de los derechos de ayuda por herencia al heredero que continúe. El fallecimiento se considera fuerza mayor, de modo que los incumplimientos que cause no hacen perder las ayudas de la campaña.",quien:"Heredero que continúe",org:"Consejería de agricultura / FEGA",docs:["Certificado de defunción","Título sucesorio","Solicitud única"],norma:"Reglamento (UE) 2021/2116, art. 3; RD 1045/2022 (derechos de ayuda básica a la renta)",e:TP,cuando:(c)=>c.situ.pac},
{id:"rega",fase:"titularidad",t:"Explotación ganadera: cambio de titular en el REGA",d:"El heredero que continúe debe comunicar el cambio de titular de la explotación y de los animales en el registro de explotaciones ganaderas; si cesa, debe darla de baja y vender o trasladar los animales conforme a las normas sanitarias.",quien:"Heredero",org:"Oficina comarcal agraria",docs:["Título sucesorio","Libro de explotación"],norma:"RD 479/2004 (Registro general de explotaciones ganaderas)",e:TP,cuando:(c)=>c.situ.ganado},
{id:"arrendamiento_rustico",fase:"titularidad",t:"Arrendamientos rústicos",d:"Si el fallecido era arrendatario de fincas rústicas, el contrato se extingue, salvo el derecho de sus sucesores a continuarlo en los términos de la ley. Si era arrendador, los herederos le suceden en el contrato y deben comunicarlo al arrendatario.",quien:"Herederos",org:"Arrendador o arrendatario",docs:["Contrato de arrendamiento"],norma:"art. 24.e Ley 49/2003 de Arrendamientos Rústicos",e:TV,cuando:(c)=>c.situ.rustica},
{id:"regantes",fase:"titularidad",t:"Comunidad de regantes y concesiones de agua",d:"Si las fincas tienen derecho de riego o un pozo inscrito, hay que comunicar el cambio de titular a la comunidad de regantes y al organismo de cuenca para que conste en el Registro de Aguas.",quien:"Herederos",org:"Comunidad de regantes / confederación hidrográfica",docs:["Título sucesorio","Datos de la concesión"],norma:"RDLeg 1/2001 (TR Ley de Aguas) y Reglamento del Dominio Público Hidráulico",e:TP,cuando:(c)=>c.situ.rustica},
{id:"continuar_negocio",fase:"titularidad",t:"Continuar el negocio del autónomo",d:"El heredero que siga con la actividad se da de alta como autónomo y en Hacienda, cambia a su nombre licencias, contratos y cuentas del negocio y se subroga en los trabajadores. La transmisión por herencia no genera ganancia en el IRPF del fallecido y la empresa familiar puede tener reducción en el impuesto.",quien:"Heredero que continúa",org:"AEAT, Seguridad Social y ayuntamiento",docs:["Título sucesorio","Licencia de actividad"],norma:"art. 44 Estatuto de los Trabajadores; art. 33.3.b LIRPF; art. 20.2.c Ley 29/1987",e:TP,cuando:(c)=>c.situ.autonomo},
{id:"licencias",fase:"titularidad",t:"Licencias transmisibles: taxi, farmacia, estanco, lotería",d:"No pasan automáticamente al heredero: cada normativa fija si puede continuar, en qué plazo debe pedir la transmisión y qué requisitos debe cumplir (por ejemplo, ser farmacéutico o tener permiso profesional). Si no los cumple, suele tener un plazo para transmitirla.",quien:"Herederos",org:"Ayuntamiento, consejería, Comisionado para el Mercado de Tabacos o SELAE",docs:["Título de la licencia","Título sucesorio"],norma:"normativa sectorial (autonómica de farmacia y taxi; RD 1199/1999 para expendedurías de tabaco)",e:TP,cuando:(c)=>c.situ.licencia},
{id:"sociedad_civil",fase:"titularidad",t:"Sociedad civil o comunidad de bienes",d:"La sociedad civil se disuelve por la muerte de un socio, salvo pacto de continuar con sus herederos. En una comunidad de bienes con actividad hay que comunicar a Hacienda el cambio de comuneros (modelo 036) y liquidar o repartir la parte del fallecido.",quien:"Herederos y demás socios",org:"Agencia Tributaria",docs:["Contrato de sociedad o comunidad"],norma:"arts. 1700.3 y 1704 CC; RD 1065/2007 (declaración censal)",e:TP,cuando:(c)=>c.situ.sociedadCivil},
{id:"derechos_autor",fase:"titularidad",t:"Derechos de autor",d:"Los derechos de explotación de sus obras duran setenta años tras su muerte y pasan a los herederos. Comunica la herencia a las entidades de gestión (SGAE, CEDRO, VEGAP, AIE...) y a las editoriales para seguir cobrando.",quien:"Herederos",org:"Entidades de gestión y editoriales",docs:["Título sucesorio","Contratos de edición"],norma:"arts. 15, 26 y 42 TR Ley de Propiedad Intelectual (RDLeg 1/1996)",e:TV,cuando:(c)=>c.situ.autor},
{id:"propiedad_industrial",fase:"titularidad",t:"Patentes y marcas: inscribir al heredero",d:"Patentes, modelos y marcas se transmiten por herencia, pero la transmisión debe inscribirse en la Oficina Española de Patentes y Marcas para oponerla a terceros. Vigila las tasas de mantenimiento y renovación para que no caduquen.",quien:"Herederos",org:"Oficina Española de Patentes y Marcas",docs:["Título sucesorio","Número de registro"],accion:{tipo:"sede",url:SEDES.oepm,texto:"Abrir la OEPM"},norma:"Ley 17/2001 de Marcas y Ley 24/2015 de Patentes (transmisiones)",e:TP,cuando:(c)=>c.situ.autor},
{id:"embarcacion",fase:"titularidad",t:"Transferir la embarcación",d:"El cambio de titular por herencia se anota en el Registro de Buques de la Capitanía Marítima donde está matriculada. Revisa también el seguro obligatorio y, si tiene amarre en un puerto, el contrato o la concesión.",quien:"Heredero adjudicatario",org:"Capitanía Marítima",docs:["Título sucesorio","Justificante del impuesto","Permiso de navegación"],accion:{tipo:"sede",url:SEDES.buques,texto:"Ver en Transportes"},norma:"RD 1435/2010 (matriculación de embarcaciones de recreo)",e:TP,cuando:(c)=>c.situ.embarcacion},
{id:"aeronave",fase:"titularidad",t:"Transferir la aeronave",d:"El cambio de titular de aeronaves y ultraligeros se inscribe en el Registro de Matrícula de Aeronaves y, si procede, en el Registro de Bienes Muebles.",quien:"Heredero adjudicatario",org:"Agencia Estatal de Seguridad Aérea / Registro de Bienes Muebles",docs:["Título sucesorio","Certificado de matrícula"],norma:"Ley 48/1960 sobre Navegación Aérea",e:TP,cuando:(c)=>c.situ.aeronave},
{id:"bajas",fase:"titularidad",t:"Bajas de suscripciones, tarjetas y servicios",d:"Plataformas, prensa, gimnasio, telefonía, tarjetas de fidelización y domiciliaciones que ya no tienen sentido.",quien:"Familia",org:"",docs:["Certificado de defunción"],norma:"",e:TV,cuando:()=>true},
{id:"irpf",fase:"despues",t:"Última declaración de la renta del fallecido",d:"Del 1 de enero al día del fallecimiento. La presentan los herederos en la campaña del año siguiente.",quien:"Herederos",org:"Agencia Tributaria",plazo:(c)=>{const a=Number(c.fecha.slice(0,4))+1;return{desde:`${a}-04-01`,limite:`${a}-06-30`,nota:"fechas de campaña aproximadas"};},docs:["Certificados de retenciones","Datos fiscales"],accion:{tipo:"sede",url:SEDES.aeat,texto:"Abrir la sede de la AEAT"},norma:"LIRPF, arts. 14.4 y 97",e:TP,cuando:()=>true},
{id:"irpf_anterior",fase:"despues",t:"Renta del año anterior, si no llegó a presentarla",d:"Si falleció antes de presentar la declaración del año anterior, los herederos deben presentarla en su campaña.",quien:"Herederos",org:"Agencia Tributaria",plazo:(c)=>{const a=Number(c.fecha.slice(0,4));return{limite:`${a}-06-30`,info:true,nota:"solo si aún no estaba presentada"};},docs:["Datos fiscales"],accion:{tipo:"sede",url:SEDES.aeat,texto:"Abrir la sede de la AEAT"},norma:"LIRPF arts. 13, 14.4 y 97.4; LGT art. 39.1",e:TP,cuando:(c)=>c.fecha.slice(5)<"07-01"},
{id:"ibi_anual",fase:"despues",t:"IBI del año del fallecimiento",d:"Lo debe quien era titular el 1 de enero: la herencia lo paga y se reparte entre los herederos.",quien:"Herederos",org:"Ayuntamiento",docs:[],norma:"art. 75 TRLRHL",e:TV,cuando:(c)=>c.inmuebles>0},
{id:"permanencia",fase:"despues",t:"Mantener la vivienda para no perder la reducción",d:"La reducción por vivienda habitual exige conservarla el tiempo que marca la ley. Venderla antes obliga a pagar lo reducido con intereses.",quien:"Herederos que la aplicaron",org:"Hacienda autonómica",plazo:(c)=>({limite:trMeses(c.fecha,12*(c.permanenciaVivienda||5)),info:true}),docs:[],norma:"art. 20.2.c Ley 29/1987 y normativa autonómica",e:TV,cuando:(c)=>c.permanenciaVivienda>0},
{id:"cuentas",fase:"despues",t:"Rendir cuentas entre herederos",d:"Quien adelantó gastos comunes tiene derecho a que los demás le paguen su parte. Conviene cerrar las cuentas por escrito.",quien:"Herederos",org:"",docs:["Facturas y justificantes"],norma:"arts. 1063-1064 CC",e:TV,cuando:(c)=>c.nHerederos>1},
{id:"prescripcion",fase:"despues",t:"Guardar justificantes hasta la prescripción",d:"Hacienda puede comprobar los valores durante cuatro años desde que acaba el plazo de presentación (más si se pidió prórroga). Si discrepa de un valor comprobado, cabe la tasación pericial contradictoria; contra el valor de referencia del Catastro, no.",quien:"Herederos",org:"Hacienda autonómica",plazo:(c)=>({limite:trPrescripcion(c),info:true}),docs:[],norma:"arts. 66-67 y 135 Ley General Tributaria",e:TV,cuando:()=>true},
{id:"irpf_rentas_pendientes",fase:"despues",t:"Rentas pendientes de imputar en la última renta",d:"Las rentas que el fallecido tenía pendientes de imputar (cobros aplazados, atrasos que se pagan después) se incluyen en su última declaración. Los herederos pueden pedir fraccionar la parte de la cuota que corresponde a esas rentas.",quien:"Herederos",org:"Agencia Tributaria",docs:[],norma:"art. 14.4 LIRPF y Reglamento del IRPF",e:TP,cuando:(c)=>c.situ.trabajador||c.situ.autonomo||c.situ.arrendador||c.situ.pensionista},
{id:"modelo184",fase:"despues",t:"Herencia sin repartir con rentas: modelo 184",d:"Mientras la herencia no se reparta, si produce rentas (alquileres, actividad) por encima de 3.000 € al año, debe presentar cada enero la declaración informativa de entidades en atribución de rentas; cada heredero declara su parte en su IRPF.",quien:"Herederos o gestoría",org:"Agencia Tributaria",plazo:(c)=>({limite:`${anio(c)+1}-01-31`,nota:"cada enero mientras siga sin repartir"}),docs:["NIF de la herencia yacente","Ingresos y gastos"],accion:{tipo:"sede",url:SEDES.m184,texto:"Modelo 184 en la AEAT"},norma:"art. 90 LIRPF; art. 70 Reglamento del IRPF",e:TP,cuando:(c)=>c.situ.arrendador||c.situ.vut||c.situ.autonomo},
{id:"modelo720",fase:"despues",t:"Bienes en el extranjero: modelos 720 y 721",d:"Los herederos residentes que reciban cuentas, valores, seguros o inmuebles situados fuera de España por más de 50.000 € por grupo deben declararlos en el modelo 720, y las criptomonedas custodiadas fuera en el modelo 721, entre enero y marzo del año siguiente.",quien:"Herederos residentes",org:"Agencia Tributaria",plazo:(c)=>({limite:`${anio(c)+1}-03-31`,desde:`${anio(c)+1}-01-01`}),docs:["Certificados de saldos y valores en el extranjero"],accion:{tipo:"sede",url:SEDES.m720,texto:"Modelo 720 en la AEAT"},norma:"disposición adicional 18.ª LGT; arts. 42 bis a 42 quater RD 1065/2007",e:TP,cuando:(c)=>c.situ.extranjero||c.situ.cripto},
{id:"irnr",fase:"despues",t:"Heredero no residente con inmuebles en España",d:"El heredero que no reside en España tributa cada año por los inmuebles heredados en el Impuesto sobre la Renta de no Residentes (modelo 210): por la renta imputada si no los alquila y por los alquileres si los alquila. Si vende, el comprador retiene el 3 % del precio.",quien:"Heredero no residente",org:"Agencia Tributaria",docs:["Recibo del IBI","Datos catastrales"],accion:{tipo:"sede",url:SEDES.m210,texto:"Modelo 210 en la AEAT"},norma:"RDLeg 5/2004 (TR Ley del IRNR), arts. 13, 24 y 25",e:TP,cuando:(c)=>c.situ.herederoExtranjero&&c.inmuebles>0},
{id:"empresa_permanencia",fase:"despues",t:"Mantener la empresa para no perder la reducción",d:"La reducción por empresa familiar exige conservar lo recibido durante diez años (menos en algunas comunidades) y no hacer actos que minoren su valor. Si no se cumple, hay que pagar lo reducido con intereses.",quien:"Herederos que la aplicaron",org:"Hacienda autonómica",plazo:(c)=>({limite:trMeses(c.fecha,120),info:true,nota:"plazo estatal; revisar el autonómico"}),docs:[],norma:"art. 20.2.c Ley 29/1987 y normativa autonómica",e:TP,cuando:(c)=>c.hayEmpresa},
{id:"comprobacion",fase:"despues",t:"Si Hacienda comprueba valores: tasación pericial contradictoria",d:"Si Hacienda notifica un valor mayor que el declarado, se puede alegar y, contra la liquidación, pedir una tasación pericial contradictoria dentro del plazo del primer recurso, lo que suspende la liquidación. No cabe frente al valor de referencia del Catastro, que se discute recurriendo la liquidación.",quien:"Abogado y perito",org:"Hacienda autonómica",plazo:()=>({nota:"un mes desde la notificación de la liquidación"}),docs:["Liquidación y valoración notificadas","Informe pericial"],norma:"arts. 57, 134 y 135 LGT",e:TP,cuando:()=>true},
{id:"recursos",fase:"despues",t:"Recurrir una liquidación o sanción",d:"Contra una liquidación del impuesto o de la plusvalía cabe recurso de reposición o reclamación económico-administrativa en un mes desde la notificación, y después recurso contencioso-administrativo en dos meses. Se puede pedir la suspensión aportando garantía.",quien:"Abogado",org:"Hacienda autonómica / ayuntamiento / tribunales",plazo:()=>({nota:"un mes desde cada notificación"}),docs:["Notificación que se recurre"],norma:"arts. 222-236 LGT; art. 14 TRLRHL; art. 46 Ley 29/1998 de la Jurisdicción Contencioso-administrativa",e:TP,cuando:()=>true},
{id:"rectificacion",fase:"despues",t:"Pedir la devolución si se pagó de más",d:"Si se descubre un error (una deuda no restada, una reducción no aplicada, un valor excesivo), se puede pedir la rectificación de la autoliquidación y la devolución con intereses durante cuatro años.",quien:"Herederos",org:"Hacienda autonómica / ayuntamiento",plazo:(c)=>({limite:trPrescripcion(c),info:true}),docs:["Autoliquidación","Justificantes del error"],norma:"art. 120.3 LGT; arts. 126-129 RD 1065/2007",e:TP,cuando:()=>true},
{id:"adicion_herencia",fase:"despues",t:"Bienes que aparecen después: adición a la partición",d:"Si aparece un bien no incluido, no se anula el reparto: se otorga una escritura de adición y se presenta una autoliquidación complementaria del impuesto por lo nuevo.",quien:"Herederos",org:"Notaría / Hacienda autonómica",docs:["Documentación del bien","Escritura de partición"],norma:"art. 1079 CC; art. 122 LGT",e:TP,cuando:()=>true},
{id:"condominio",fase:"despues",t:"Si quedan bienes en común: extinguir el condominio",d:"Los bienes adjudicados a varios herederos en proindiviso pueden dividirse después: adjudicándolos a uno que compense a los demás, vendiéndolos, o por la acción judicial de división de cosa común, que cualquiera puede ejercitar. La extinción por acuerdo tributa en Actos Jurídicos Documentados.",quien:"Copropietarios",org:"Notaría o juzgado",docs:["Escritura de partición"],norma:"arts. 400-406 y 1062 CC; art. 31.2 RDLeg 1/1993",e:TP,cuando:(c)=>c.nHerederos>1&&c.inmuebles>0},
{id:"venta_inmueble",fase:"despues",t:"Si se vende un inmueble heredado",d:"En el IRPF del heredero la ganancia se calcula desde el valor declarado en el Impuesto sobre Sucesiones: declarar un valor bajo encarece la venta. La venta genera de nuevo plusvalía municipal y puede hacer perder la reducción por vivienda habitual si no se ha cumplido la permanencia.",quien:"Herederos que venden",org:"Agencia Tributaria / ayuntamiento",docs:["Autoliquidación del impuesto","Escritura de herencia"],norma:"art. 36 LIRPF; art. 104 TRLRHL",e:TP,cuando:(c)=>c.inmuebles>0},
{id:"rescision_particion",fase:"despues",t:"Partición con lesión: rescisión en cuatro años",d:"Si a un heredero se le adjudicó menos de tres cuartas partes de lo que le correspondía, según los valores al tiempo de la partición, puede pedir la rescisión en los cuatro años siguientes. Los demás pueden evitarla compensándole.",quien:"Heredero perjudicado",org:"Juzgado de Primera Instancia",docs:["Escritura de partición","Tasaciones"],norma:"arts. 1073-1081 CC",e:TP,cuando:(c)=>c.nHerederos>1},
{id:"albacea_cuentas",fase:"despues",t:"Rendición de cuentas del albacea o contador-partidor",d:"El albacea tiene un año desde que aceptó para cumplir su encargo, salvo prórroga del testamento o de los herederos, y al terminar debe rendir cuentas de su gestión a los herederos.",quien:"Albacea",org:"",docs:["Justificantes de su gestión"],norma:"arts. 904-907 CC",e:TP,cuando:(c)=>c.situ.albacea},
{id:"curatela_cuentas",fase:"despues",t:"Si tenía curador: rendición final de cuentas",d:"El curador cesa con la muerte de la persona a la que apoyaba y debe rendir ante el juzgado la cuenta general de su administración en tres meses y entregar bienes y documentos a los herederos.",quien:"Curador",org:"Juzgado",plazo:(c)=>({limite:trMeses(c.fecha,3)}),docs:["Inventario y cuentas de la curatela"],norma:"arts. 291 y 292 CC",e:TP,cuando:(c)=>c.situ.teniaCurador},
{id:"ivtm",fase:"despues",t:"Impuesto de circulación de los vehículos",d:"Lo debe quien figure como titular el 1 de enero. Si el vehículo se da de baja, se puede pedir la devolución proporcional de los trimestres que falten.",quien:"Herederos",org:"Ayuntamiento",docs:[],norma:"art. 96 TRLRHL",e:TP,cuando:(c)=>c.hayVehiculos},
];
